  'Photography',
  'Photography is a studio course in image-making with light, cameras, digital workflow, history, critique, and visual storytelling. Students learn exposure, optics, composition, lighting, digital editing, black and white, color, portraiture, documentary practice, staged and conceptual photography, analog and alternative processes, sequencing, photobooks, exhibition design, ethics, copyright, and portfolio presentation. The course treats photography as both technical craft and a cultural form that shapes memory, evidence, identity, and public life.',
  $photjson${"slug": "photography", "title": "Photography", "description": "Photography is a studio course in image-making with light, cameras, digital workflow, history, critique, and visual storytelling. Students learn exposure, optics, composition, lighting, digital editing, black and white, color, portraiture, documentary practice, staged and conceptual photography, analog and alternative processes, sequencing, photobooks, exhibition design, ethics, copyright, and portfolio presentation. The course treats photography as both technical craft and a cultural form that shapes memory, evidence, identity, and public life.", "topics": [{"id": "bf7c9774-6af3-44ea-9f54-ebb82001912d", "type": "topic", "title": "Photographic Seeing, History, and Visual Culture", "description": "This opening unit treats photography as both technical craft and cultural language. Students learn how photographs make meaning through seeing, selection, framing, technology, circulation, and history.", "children": [{"id": "a9155988-cd16-49ae-b3fa-6072a069fb88", "type": "subtopic", "title": "Photography as a medium", "children": [{"id": "e6d73ac2-053a-4922-8672-46c12b5687dc", "type": "concept", "title": "Light as material"}, {"id": "38450abc-e8a0-4b60-800b-b14ff89fd2ee", "type": "concept", "title": "The camera as a choosing machine"}, {"id": "26f8613d-d950-4275-9350-be6ceffc4efd", "type": "concept", "title": "Evidence, memory, fiction, and document"}, {"id": "3e6678e8-a66e-4b78-8246-fd1b30269f2d", "type": "concept", "title": "Photography across art, journalism, science, commerce, and everyday life"}], "description": "Students learn what makes photography distinct: index, light, time, optics, apparatus, evidence, fiction, and point of view."}, {"id": "90d39b13-54b4-447a-af31-7b6119cf5bc0", "type": "subtopic", "title": "Histories of photography", "children": [{"id": "fb54c99c-18e7-42a1-b05c-79e6c1f03289", "type": "concept", "title": "Camera obscura and early processes"}, {"id": "27146f56-54b5-4835-9c30-d29fb68e9e27", "type": "concept", "title": "Pictorialism, modernism, and straight photography"}, {"id": "18f484f9-d3d4-4426-945e-ec5fc60c444f", "type": "concept", "title": "Documentary and social reform traditions"}, {"id": "eb68e69f-4486-446d-a911-769e67c6d02c", "type": "concept", "title": "Color, postmodernism, and contemporary lens-based practice"}], "description": "The goal is to situate current practice in a lineage from early processes through modernism, documentary, color, conceptual, digital, and networked image culture."}, {"id": "7e2c8197-b74a-48e7-95b3-8110bfa1aa5d", "type": "subtopic", "title": "Visual culture and image circulation", "children": [{"id": "0062ec6d-18c7-41a3-a420-e7345c10c893", "type": "concept", "title": "Photobooks and magazines"}, {"id": "0c8f0e11-dc68-4455-8a09-fd3a3661fa61", "type": "concept", "title": "Museums and archives"}, {"id": "73515d1f-105d-4f9e-a747-11aebc2e6d7d", "type": "concept", "title": "Social media and platforms"}, {"id": "dacac15c-cd55-45a0-892a-73634ddb87bc", "type": "concept", "title": "Image economies, attention, and reproduction"}], "description": "Students examine how photographs live in books, galleries, screens, archives, feeds, newspapers, ads, and family albums."}]}, {"id": "2f0bca49-dd7d-4957-ab2c-27efeafe3ee9", "type": "topic", "title": "Camera Systems, Exposure, Focus, and Optics", "description": "A strong photographer controls the camera deliberately. This unit builds fluency with exposure, focus, focal length, sensor or film behavior, lens choice, and image quality.", "children": [{"id": "80d662e2-c681-4653-8223-933f3a3a5c80", "type": "subtopic", "title": "Camera operation and exposure", "children": [{"id": "570f17bd-5a09-4562-8072-33f05a1a04b8", "type": "concept", "title": "Manual, aperture priority, and shutter priority modes"}, {"id": "fa7626e3-d23d-4d36-85d5-28b4193e503c", "type": "concept", "title": "Metering and exposure compensation"}, {"id": "f064e7d4-33fd-446e-a5a5-ccff9061ce2f", "type": "concept", "title": "Histograms and dynamic range"}, {"id": "abdb2e43-3225-4122-a215-fe5ef779f064", "type": "concept", "title": "Exposure bracketing and difficult light"}], "description": "Students learn how aperture, shutter speed, and ISO work together to shape brightness, motion, grain, depth of field, and intention."}, {"id": "b675b0bd-0991-4276-82f6-6bcf3f8f35c3", "type": "subtopic", "title": "Focus and lens behavior", "children": [{"id": "41d86825-ef46-438f-840f-e8d39aae022e", "type": "concept", "title": "Focal length and field of view"}, {"id": "6d2aa9c3-73c6-4495-bbea-099a557f18e2", "type": "concept", "title": "Depth of field and hyperfocal distance"}, {"id": "976b2ba1-de25-49a8-a1f2-7dc967eef3ca", "type": "concept", "title": "Autofocus modes and manual focus"}, {"id": "063d8bb6-37c7-4c4b-abd3-9070f2ca0a7a", "type": "concept", "title": "Lens distortion, compression, and perspective"}], "description": "The point is to understand how optics change spatial relationships, attention, and photographic voice."}, {"id": "34fd03ca-b3f8-4514-a7d4-db0dd5282b19", "type": "subtopic", "title": "Capture formats and technical quality", "children": [{"id": "5efa9528-e097-45ad-89ec-762887bfd75d", "type": "concept", "title": "RAW versus JPEG"}, {"id": "518f8728-961b-4de8-8727-0ab94de84d60", "type": "concept", "title": "Sensor size and aspect ratio"}, {"id": "bcacb31d-c08f-4140-8857-b77ea451cd4c", "type": "concept", "title": "Bit depth and compression"}, {"id": "84c420b8-f43d-4e90-986e-891e9424dfb9", "type": "concept", "title": "Tripods, stabilization, and sharpness"}], "description": "Students learn practical decisions that affect resolution, noise, color latitude, editing flexibility, and final output."}]}, {"id": "fa2f4bf3-e134-4012-98b7-aef062889cab", "type": "topic", "title": "Composition, Framing, Light, and Time", "description": "Composition is not a rulebook; it is the organization of attention. This unit helps students use frame, edge, timing, gesture, geometry, and light to make photographs that feel intentional.", "children": [{"id": "e4493081-628d-4438-84a6-6eb7b18d4166", "type": "subtopic", "title": "Frame and composition", "children": [{"id": "5ab1b73e-f2e0-4927-b4f5-b97064a7b47d", "type": "concept", "title": "Figure-ground relationships"}, {"id": "56132a0a-75c6-40c8-842f-5d18496ca219", "type": "concept", "title": "Balance, tension, rhythm, and repetition"}, {"id": "b370551f-bcd7-47eb-895e-90b0af7520b9", "type": "concept", "title": "Foreground, middle ground, and background"}, {"id": "6fc646c0-1584-4e4d-b7af-37f14bf3baae", "type": "concept", "title": "Cropping, aspect ratio, and edge control"}], "description": "Students learn how placement, scale, relation, edge, and empty space control how viewers move through an image."}, {"id": "92fc1edb-1a13-4f8e-a5ec-7f231f59941c", "type": "subtopic", "title": "Light as structure", "children": [{"id": "a440d199-e5e3-4fb4-a67b-0bff6531fec1", "type": "concept", "title": "Direction, quality, intensity, and color"}, {"id": "c142fbd6-95d0-42cd-8d00-6cccf79da132", "type": "concept", "title": "Backlight, sidelight, silhouette, and reflection"}, {"id": "e00cf411-0452-4843-9d5f-6c6b614b2896", "type": "concept", "title": "Natural light and available light"}, {"id": "18e2c158-26a4-4965-bb64-8b3cf561a005", "type": "concept", "title": "Shadow, contrast, and mood"}], "description": "Students study how light reveals, hides, dramatizes, flattens, separates, or transforms a subject."}, {"id": "f24d2cd5-48ee-409f-8863-5deb84bee066", "type": "subtopic", "title": "Time and decisive attention", "children": [{"id": "478a2dea-cf0c-45b9-aecb-d9d711b81fe0", "type": "concept", "title": "Freezing and blurring motion"}, {"id": "3a4fd319-17e8-476d-a278-f611b8cd57d2", "type": "concept", "title": "The decisive moment and its critiques"}, {"id": "ed2d1fb1-43e0-4356-8925-2b66824aba55", "type": "concept", "title": "Long exposure and accumulated time"}, {"id": "801249ce-f32f-4c1b-a3f8-f578cf5d18a6", "type": "concept", "title": "Sequence, repetition, and contact-sheet thinking"}], "description": "The unit connects shutter speed to gesture, duration, anticipation, and the ethics of choosing a moment."}]}, {"id": "e19711e9-e2d6-4018-b82e-b7bf5f577e60", "type": "topic", "title": "Digital Capture Workflow, File Management, and Color Management", "description": "A photography course teaches durable workflow habits. Students learn how to ingest, name, back up, edit, color-manage, and preserve image files without losing quality or context.", "children": [{"id": "28ada255-f9e4-41de-91f7-30501388d2a8", "type": "subtopic", "title": "Ingest, backup, and cataloging", "children": [{"id": "42fa0993-fad0-4b84-8a58-382998cab00c", "type": "concept", "title": "Folder structures and file naming"}, {"id": "75e17e14-a45f-47c0-88b5-a56e90f001d7", "type": "concept", "title": "Metadata, keywords, ratings, and captions"}, {"id": "123c46ae-905c-452b-a581-c16fb10d02a9", "type": "concept", "title": "3-2-1 backup strategy"}, {"id": "d3feb6d7-d30e-4736-aaa6-b0114471ff05", "type": "concept", "title": "Contact sheets and edit selects"}], "description": "Students learn a professional workflow that makes work findable, recoverable, and editable over time."}, {"id": "e091e78e-c5cb-47d0-b0e4-2a29f23b9193", "type": "subtopic", "title": "Color-managed workflow", "children": [{"id": "e25972cb-cf70-4215-ab40-c023c633a443", "type": "concept", "title": "White balance and profiles"}, {"id": "a32c747c-c237-47d7-8cdc-340a588b0e9b", "type": "concept", "title": "Monitor calibration concepts"}, {"id": "ff1eb37c-622e-45aa-8391-583747372386", "type": "concept", "title": "Soft proofing and output profiles"}, {"id": "5474df19-210b-4844-804b-280d3622e087", "type": "concept", "title": "Color spaces: sRGB, Adobe RGB, and ProPhoto RGB"}], "description": "Students learn why color shifts across cameras, monitors, printers, papers, and web platforms."}, {"id": "5bb93019-96bd-4a2a-8311-28f0a0385c7f", "type": "subtopic", "title": "Digital asset preservation", "children": [{"id": "8e1bf9a6-f9df-4c10-bb93-7635f4ac4b2d", "type": "concept", "title": "RAW files and sidecar data"}, {"id": "54fdc053-52be-452b-9353-b3da42e60369", "type": "concept", "title": "Non-destructive editing"}, {"id": "3346eed8-15ad-49b6-8ad6-53dbab05301e", "type": "concept", "title": "Versioning and exports"}, {"id": "5e16a07f-389f-4f63-9ed8-d3ec9b61c954", "type": "concept", "title": "Long-term storage and archive documentation"}], "description": "The goal is to treat photographs as an archive, not just exported images."}]}, {"id": "711bb8fb-72fe-4173-ba42-a58f8b79329f", "type": "topic", "title": "Lightroom, Photoshop, Editing, Retouching, and Output", "description": "Editing is part of photographic authorship. This unit teaches students to move from capture to resolved image through selection, tonal control, color correction, retouching, compositing awareness, and output.", "children": [{"id": "7e12bd87-e8dd-47c8-ad32-03a85e31e585", "type": "subtopic", "title": "Image selection and editing judgment", "children": [{"id": "84a85016-29ca-4581-9be7-c3bb6cd3c0ba", "type": "concept", "title": "Rating and culling systems"}, {"id": "fb278065-3b7a-4b5c-bb54-19dbd3051ef5", "type": "concept", "title": "Comparing similar frames"}, {"id": "272c3bc1-3240-41e0-979f-67ea3bc2a76b", "type": "concept", "title": "Edit for project coherence"}, {"id": "01edf555-2aa5-42e2-ab6e-028665d9168c", "type": "concept", "title": "Avoiding over-selection and attachment"}], "description": "Students learn to choose images by intention, sequence, formal strength, and ethical suitability rather than by technical perfection alone."}, {"id": "fe1bd552-6533-43c5-8bc4-d58effd46ac5", "type": "subtopic", "title": "Global and local adjustments", "children": [{"id": "0fe7da4c-d7a1-4066-bfe1-5113acd4899f", "type": "concept", "title": "Exposure, contrast, highlights, and shadows"}, {"id": "3f81a8fb-b7ba-4012-9fef-b94b2cc2d923", "type": "concept", "title": "Curves and tonal mapping"}, {"id": "9e5136a7-8a61-47f9-b205-582232b35362", "type": "concept", "title": "Masks, gradients, and local corrections"}, {"id": "58593876-c673-4e1f-9cae-3f5f249616c0", "type": "concept", "title": "Noise reduction and sharpening"}], "description": "Students practice making changes that support the photograph instead of calling attention to software."}, {"id": "426109fb-606f-4944-86ea-81dcd3eea568", "type": "subtopic", "title": "Retouching and output", "children": [{"id": "ef326a60-827e-4cd6-800a-71b3b910d300", "type": "concept", "title": "Dust spotting and cleanup"}, {"id": "7a75b441-f8c4-4300-bb85-38ca0849f0cd", "type": "concept", "title": "Skin and object retouching ethics"}, {"id": "6493d19c-be56-48eb-86bc-0d8ff840d263", "type": "concept", "title": "Export for print, web, portfolio, and projection"}, {"id": "72671a79-cdbb-461a-95dc-1d89e378daf2", "type": "concept", "title": "File formats and resolution requirements"}], "description": "The unit balances polish with credibility, teaching students what can be changed, what should be disclosed, and how files should leave the workspace."}]}, {"id": "fd726c69-99ab-4a54-801b-b5c472ddd1bf", "type": "topic", "title": "Black and White Photography and Tonal Craft", "description": "Black and white photography sharpens attention to light, tone, structure, texture, and form. Students learn how monochrome choices change meaning and how tonal craft supports visual clarity.", "children": [{"id": "e7ac51cf-a838-4f2b-b69c-71b6801de5db", "type": "subtopic", "title": "Seeing in tone", "children": [{"id": "00b9f04f-6afc-430b-a433-628df95cb11b", "type": "concept", "title": "Value scale and tonal separation"}, {"id": "a7af3ac7-a17a-4396-8b28-d7ced38bec20", "type": "concept", "title": "Texture and surface"}, {"id": "e5d5daaf-880e-46ce-8ce3-0030d5532032", "type": "concept", "title": "High-key and low-key imagery"}, {"id": "5ac71d9c-5587-4135-b3db-bc3e69928e8d", "type": "concept", "title": "Monochrome previsualization"}], "description": "Students train themselves to perceive luminance, contrast, texture, and shape without relying on color."}, {"id": "4ce09b24-15f7-4841-ba11-00958f09447b", "type": "subtopic", "title": "Black and white conversion", "children": [{"id": "ee84a9aa-4de2-4b5a-b4ac-2a08752a480b", "type": "concept", "title": "Channel mixing and color filters"}, {"id": "49616267-f34d-4d86-91e3-fff83fb35e2d", "type": "concept", "title": "Curves and contrast control"}, {"id": "2e81e4ae-39cb-4210-bea0-d6871a1c662e", "type": "concept", "title": "Dodging and burning"}, {"id": "5bde8cf9-d3ea-4018-a496-99293ab190d9", "type": "concept", "title": "Grain, clarity, and sharpening"}], "description": "Students learn how digital conversions are interpretive decisions, not automatic desaturation."}, {"id": "fcc202bd-6705-4c52-b6a4-1ef61f85b9d7", "type": "subtopic", "title": "Black and white traditions", "children": [{"id": "8596fbdc-d251-4872-a769-03df33994b54", "type": "concept", "title": "Documentary black and white"}, {"id": "03c3329e-025e-4860-9ef2-8c2f8cb0072a", "type": "concept", "title": "Modernist form and abstraction"}, {"id": "13ef5952-1922-405a-afbe-42974010ca39", "type": "concept", "title": "Portraiture and atmosphere"}, {"id": "d868d680-0ad1-4d82-b041-4c5d81a01fe0", "type": "concept", "title": "Archival and fine-art print references"}], "description": "The unit links tonal practice to major photographic histories and contemporary uses."}]}, {"id": "0cff92c7-216e-41e1-b321-31bd0525a2e8", "type": "topic", "title": "Color Photography, White Balance, and Color Meaning", "description": "Color is technical, perceptual, emotional, and cultural. This unit teaches students to control color accuracy when needed and use color subjectively when meaning calls for it.", "children": [{"id": "ca40827b-2a0f-49b3-9914-8446e371dbae", "type": "subtopic", "title": "White balance and color accuracy", "children": [{"id": "f9e8c8ce-5e9c-4b95-86ac-a64d95a2efb3", "type": "concept", "title": "Kelvin temperature"}, {"id": "2a6c9630-5331-4540-9ee5-941a694dab9d", "type": "concept", "title": "Tint and mixed lighting"}, {"id": "362e6e14-ecac-4cc9-9300-b6f2071e49dd", "type": "concept", "title": "Gray cards and custom white balance"}, {"id": "438b9f78-896e-4aaa-8c52-2831ca2a6877", "type": "concept", "title": "RAW correction and color profiles"}], "description": "Students learn how cameras interpret light color and how to correct or preserve color casts."}, {"id": "f9c4a986-c010-4f35-9e76-4c1b0dcfb341", "type": "subtopic", "title": "Color relationships and mood", "children": [{"id": "630aba33-e08c-46e2-8601-e8b5921dca23", "type": "concept", "title": "Hue, saturation, and luminosity"}, {"id": "56de0e33-b906-4df6-bdc2-0eab14738f5d", "type": "concept", "title": "Complementary and analogous color"}, {"id": "4000d326-b722-437c-a4e1-bf93e0e0de04", "type": "concept", "title": "Color contrast and harmony"}, {"id": "c7bf127e-d21d-4c4c-a6c5-0075fbedef9f", "type": "concept", "title": "Cultural meanings of color"}], "description": "Students develop a vocabulary for color as composition, symbolism, and atmosphere."}, {"id": "edb14695-55ed-4bbe-86bf-55583626a2e1", "type": "subtopic", "title": "Color in photographic history", "children": [{"id": "3d679d4b-7a08-4e3b-b288-336332ef025d", "type": "concept", "title": "Early color processes"}, {"id": "a0920de8-704c-4609-b09e-2ed7d02ffb9d", "type": "concept", "title": "New color photography"}, {"id": "0722d931-9d90-42d2-bdc5-fe395fe99053", "type": "concept", "title": "Color documentary"}, {"id": "d0e8a2b6-bd80-4a65-b8be-36dc2e9e9ef2", "type": "concept", "title": "Digital color grading and screen culture"}], "description": "The goal is to understand how color moved from commercial or amateur associations into art, documentary, and contemporary practice."}]}, {"id": "085d6454-3b8b-456e-ae36-844a876c456a", "type": "topic", "title": "Lighting: Natural, Studio, Flash, and Continuous", "description": "Lighting is the craft of shaping visibility. Students learn to read existing light and build controlled light for portraits, still lifes, products, interiors, and conceptual work.", "children": [{"id": "5b4af646-9b31-4aee-be85-99116a46dae0", "type": "subtopic", "title": "Natural and available light", "children": [{"id": "6e0cb01e-86c2-45b0-8595-0425c6624e29", "type": "concept", "title": "Golden hour, blue hour, and midday light"}, {"id": "40e1d1a6-4908-4139-a6a8-3470e5194b63", "type": "concept", "title": "Window light and reflectors"}, {"id": "b88ffed2-4295-4ad8-b18b-78d717427fcd", "type": "concept", "title": "Practical lights and mixed color"}, {"id": "c157a1a4-98af-41db-85df-839419b61803", "type": "concept", "title": "Location scouting for light"}], "description": "Students learn to work with daylight, ambient interiors, mixed sources, weather, time of day, and location constraints."}, {"id": "6e7b015a-52cd-4e83-b01c-5319e21bdde1", "type": "subtopic", "title": "Studio lighting fundamentals", "children": [{"id": "35963ca3-6dd0-4a46-9574-dd66bdbbe0a9", "type": "concept", "title": "Key, fill, rim, and background lights"}, {"id": "cca0cd4f-b984-4c06-89af-baf43310315c", "type": "concept", "title": "Softboxes, umbrellas, grids, flags, and reflectors"}, {"id": "be4a1514-3cb0-4066-965b-17752bd4dbf1", "type": "concept", "title": "Light ratios and inverse square law"}, {"id": "86d3442c-6dde-4696-8a27-ffd347bb829a", "type": "concept", "title": "Tethered capture and test frames"}], "description": "Students practice controlled lighting setups that make form, texture, mood, and separation legible."}, {"id": "8cf94584-f4f8-4d3d-bebc-0e7d29bfc4b8", "type": "subtopic", "title": "Flash and continuous systems", "children": [{"id": "84308690-b4a6-4879-ae28-339cf147d4c5", "type": "concept", "title": "On-camera and off-camera flash"}, {"id": "25f40313-81ae-4ba3-b9d1-53f702cb830c", "type": "concept", "title": "Sync speed and high-speed sync"}, {"id": "bafb0b85-4deb-4953-b3cc-917d1956fe37", "type": "concept", "title": "Modifiers and grip safety"}, {"id": "6971cec8-fe9e-4330-9fa8-8bc10b80ce04", "type": "concept", "title": "Lighting diagrams and repeatability"}], "description": "The unit compares speedlights, strobes, LEDs, and continuous setups so students can choose the right tool."}]}, {"id": "407f14b3-038a-41dc-ab11-8c42297c2aa1", "type": "topic", "title": "Portraiture, Studio Practice, and Subject Collaboration", "description": "Portraiture is a relationship as much as a picture. This unit focuses on trust, direction, lighting, gesture, environment, identity, consent, and collaboration with photographed people.", "children": [{"id": "f2ed92ba-8061-4524-ac01-88609e0853e9", "type": "subtopic", "title": "Portrait strategies", "children": [{"id": "0925cf17-a040-4a09-b61a-9512d9650bd3", "type": "concept", "title": "Expression, pose, and gesture"}, {"id": "0dd5be00-8dae-43b6-8aa3-89dd196ad4fa", "type": "concept", "title": "Background and environment"}, {"id": "9ec073bd-a0a5-410a-8c0e-01694dad52d3", "type": "concept", "title": "Gaze, address, and power"}, {"id": "fa82b6ce-15bf-498a-9c2f-d03d4fbb4df7", "type": "concept", "title": "Self-portraiture and identity"}], "description": "Students compare formal, environmental, candid, staged, self-portrait, and collaborative portrait approaches."}, {"id": "a37dcd2a-9ba6-4525-81ea-401729998777", "type": "subtopic", "title": "Working with subjects", "children": [{"id": "97329e00-608f-4dd6-ade1-2a591636c255", "type": "concept", "title": "Pre-shoot conversation"}, {"id": "a7fffb7b-bc32-43f1-bbe2-ab337dc579fa", "type": "concept", "title": "Model releases and expectations"}, {"id": "12ef1e2d-b52b-4224-96fd-2db2655cf794", "type": "concept", "title": "Directing without coercion"}, {"id": "3b42f971-3a06-4c62-a97c-669fa2d75e79", "type": "concept", "title": "Care, dignity, and representation"}], "description": "Students learn how communication, consent, scheduling, comfort, and direction affect both ethics and image quality."}, {"id": "2fb29abc-2748-45d8-8d2d-bc7062d2b036", "type": "subtopic", "title": "Studio portrait workflow", "children": [{"id": "bcf15dd3-735c-462e-930e-25260bda601e", "type": "concept", "title": "Lighting setups for faces and bodies"}, {"id": "90196dd0-8ecb-49d0-9a4a-5ecad615663e", "type": "concept", "title": "Lens choice and distance"}, {"id": "6ed49767-dd77-466a-bfd3-5687f0c0d015", "type": "concept", "title": "Tethering and review with subjects"}, {"id": "d80df667-19ac-4ea6-8a4e-859ee9addc7f", "type": "concept", "title": "Retouching boundaries"}], "description": "The goal is to combine technical control with human presence."}]}, {"id": "b53ec0f6-a22e-4f10-b14b-df4c8d63fb5c", "type": "topic", "title": "Documentary, Street, Photojournalism, and Visual Storytelling", "description": "Documentary photography asks students to make images about real people, places, events, and issues with care. This unit builds story structure, field practice, captions, editing, and ethical responsibility.", "children": [{"id": "46ad71ee-afb8-45db-b45c-25b25fe06acc", "type": "subtopic", "title": "Documentary approaches", "children": [{"id": "65c1fed7-f2f9-4068-8f50-c0653042a75a", "type": "concept", "title": "Observation and access"}, {"id": "3c2b74e0-ee77-40d0-b7ae-b86c9ade0637", "type": "concept", "title": "Photo essays and narrative arcs"}, {"id": "83f58337-d211-4ee3-8847-155d9701cbc6", "type": "concept", "title": "Caption and context"}, {"id": "d327989c-d2b9-4bcc-b139-1a7bafbe4e7b", "type": "concept", "title": "Long-term projects and immersion"}], "description": "Students learn that documentary ranges from observation to advocacy, essay, collaboration, and long-form research."}, {"id": "b1b93385-45ad-4a30-ae90-2efb68be0fa0", "type": "subtopic", "title": "Street and public-space photography", "children": [{"id": "c6cca3b5-5d85-4a5f-9655-24ad6f317c5f", "type": "concept", "title": "Anticipation and layering"}, {"id": "a3f99312-cca7-4511-b827-8261b4a04ce9", "type": "concept", "title": "Gesture and coincidence"}, {"id": "d5c08565-bd45-48d8-87bb-d110a54ddaee", "type": "concept", "title": "Public/private boundaries"}, {"id": "8d254c25-03af-4faf-a633-e4ae24d81e05", "type": "concept", "title": "Respectful field conduct"}], "description": "Students examine spontaneity, publicness, law, safety, consent, and the social behavior of photographing in public."}, {"id": "636d801c-76f3-48ba-a426-951cde6f450c", "type": "subtopic", "title": "Photojournalism standards", "children": [{"id": "2fd5b4c1-fdd8-4600-925c-8b44ba76238f", "type": "concept", "title": "News values and visual evidence"}, {"id": "f600489e-d2fe-458e-9bae-5ee1f958837d", "type": "concept", "title": "Caption writing and metadata"}, {"id": "df42caec-e0c9-4003-9a7e-f517a2a9b92f", "type": "concept", "title": "Editorial ethics and staging limits"}, {"id": "9985f223-d2fa-42ad-a069-75d8aa1f4975", "type": "concept", "title": "Trauma-aware reporting and minimizing harm"}], "description": "The unit introduces verification, caption accuracy, manipulation limits, deadlines, and public trust."}]}, {"id": "52a460ad-24b3-4ca1-8340-105232e93851", "type": "topic", "title": "Constructed, Conceptual, Staged, and Experimental Photography", "description": "Photography is not limited to capture. Students explore images built through staging, performance, intervention, appropriation, abstraction, process, and conceptual systems.", "children": [{"id": "ea10da0b-a84b-466d-bfc3-68da582765a1", "type": "subtopic", "title": "Staged and constructed images", "children": [{"id": "91605668-f0bc-456a-9be6-ca2a41803c2e", "type": "concept", "title": "Tableau and mise-en-scene"}, {"id": "4fc764c1-8e0e-4be4-bad0-56a1212b5cc4", "type": "concept", "title": "Performance for the camera"}, {"id": "6720d1a8-1223-4336-b23d-ee9a52ba32c3", "type": "concept", "title": "Still life and constructed scenes"}, {"id": "3183d9ce-f255-474b-af26-6ab08a904aef", "type": "concept", "title": "Fiction, fantasy, and ambiguity"}], "description": "Students learn how props, sets, performance, lighting, costume, and narrative ambiguity can create photographic worlds."}, {"id": "a7676089-d793-489f-a211-cea5bbf17c61", "type": "subtopic", "title": "Conceptual and process-based work", "children": [{"id": "2e000854-0e9f-4290-b109-dfcd199b0229", "type": "concept", "title": "Typology and seriality"}, {"id": "a7870c5e-9ec0-4f7f-b56f-17e9a0e0fc10", "type": "concept", "title": "Instruction-based work"}, {"id": "cf0480b8-c225-4c26-8682-a93b7db83df5", "type": "concept", "title": "Chance and constraint"}, {"id": "b79fce18-2b38-471e-a085-58728e09caaa", "type": "concept", "title": "Photography as idea and evidence"}], "description": "Students explore photographic projects driven by rules, systems, typologies, archives, or repeated actions."}, {"id": "0d014ec7-3b0d-4673-8a3e-835061d05fea", "type": "subtopic", "title": "Experimental image-making", "children": [{"id": "2d7fe260-e97d-450f-bec7-e1423de52166", "type": "concept", "title": "Scanography and photocollage"}, {"id": "23e5ad7d-bdc5-48f4-be0d-cb4e81fd9e86", "type": "concept", "title": "Glitch, abstraction, and distortion"}, {"id": "3ad37227-ddc0-4868-86a0-0ca662e0fb6f", "type": "concept", "title": "Projection and rephotography"}, {"id": "8f1e7edf-531f-4e3c-9b34-284eff55e21f", "type": "concept", "title": "Mixed media and installation"}], "description": "The unit invites risk with camera-less, hybrid, digital, and material methods."}]}, {"id": "a4533db6-ee81-4080-b8a8-aa15aba256d3", "type": "topic", "title": "Analog Processes, Darkroom, Alternative Processes, and Materiality", "description": "Analog and alternative processes teach students that photographs are objects, chemicals, surfaces, and time-based traces. Even digital photographers gain deeper craft from understanding material process.", "children": [{"id": "d21131ed-fa42-4d33-a58e-a58af0704443", "type": "subtopic", "title": "Film and darkroom overview", "children": [{"id": "f9409688-a878-4d81-93eb-d6a929c8632a", "type": "concept", "title": "Film stocks and formats"}, {"id": "9aa42c83-324c-4ca4-a357-b8586b20dbbf", "type": "concept", "title": "Developing, contact sheets, and negatives"}, {"id": "43dc900a-0143-433e-bc4b-b50e3e0d1e44", "type": "concept", "title": "Enlarger basics"}, {"id": "569bb842-05d0-400d-af55-9d0cd698a22d", "type": "concept", "title": "Dodging, burning, and test strips"}], "description": "Students learn the conceptual and practical foundations of film exposure, development, contact sheets, enlarging, and print evaluation."}, {"id": "b849741a-84f3-41e3-ac1d-a4e323fe5671", "type": "subtopic", "title": "Alternative and historical processes", "children": [{"id": "37f89702-d5ae-4937-a43b-177d92f2f032", "type": "concept", "title": "Cyanotype and photograms"}, {"id": "7bf9eed6-5da0-49ae-99ae-724559b4fe9f", "type": "concept", "title": "Pinhole photography"}, {"id": "9e62aa2c-7583-43cb-8450-fddb481e5ccd", "type": "concept", "title": "Salt, albumen, platinum, and gum overview"}, {"id": "235f5986-4b89-4fec-88a6-617cf0f36258", "type": "concept", "title": "Process variables and experimentation"}], "description": "Students explore hand-made photographic surfaces and the history of image technologies."}, {"id": "bcfba9a4-b303-485c-baff-4efb22a325d1", "type": "subtopic", "title": "Photograph as object", "children": [{"id": "fc31091d-b109-414a-ad9b-1adf699b21d7", "type": "concept", "title": "Paper types and surface"}, {"id": "62c1d104-1030-44ec-bfb1-790e0221a435", "type": "concept", "title": "Editioning and handling"}, {"id": "dd77a0a9-bdd1-436c-aa0f-d50715c7ba33", "type": "concept", "title": "Mounting and framing"}, {"id": "fe417e8b-c6c7-46cf-a230-7890d5929389", "type": "concept", "title": "Object care and storage"}], "description": "The goal is to think beyond screen images toward paper, scale, surface, edition, installation, and conservation."}]}, {"id": "2ae127a7-1fa1-4bef-aed6-2a3d15a96766", "type": "topic", "title": "Sequencing, Series, Photobooks, Text, and Exhibition Design", "description": "Photographs often become powerful through relation: sequence, rhythm, repetition, edit, scale, caption, and installation. This unit teaches students to make bodies of work rather than isolated good images.", "children": [{"id": "ca5bfdae-a591-42a9-bd6f-51e94461e763", "type": "subtopic", "title": "Series development", "children": [{"id": "5cfd71eb-6e30-481e-916e-0963e0db3b47", "type": "concept", "title": "Project statements and constraints"}, {"id": "95afa64a-5652-4362-8ef5-98d04acebd7b", "type": "concept", "title": "Typology and variation"}, {"id": "38445ac2-b251-42e0-bf6e-0e1f05d4e929", "type": "concept", "title": "Edit for coherence and surprise"}, {"id": "1d461968-cd45-45ec-b8fb-f7b7efc49ba7", "type": "concept", "title": "Critique of gaps and redundancies"}], "description": "Students learn how projects cohere through subject, method, visual language, concept, and edit."}, {"id": "d322c698-302d-4870-93b4-d27e4db5d418", "type": "subtopic", "title": "Sequencing and photobooks", "children": [{"id": "760a215c-53f2-4a32-8c88-8bd4cabe514a", "type": "concept", "title": "Opening and closing images"}, {"id": "8b3eaf99-ec32-4755-8ebc-1e6679658469", "type": "concept", "title": "Rhythm, pause, and transition"}, {"id": "5d48d35b-e92d-447e-9628-40c63916075c", "type": "concept", "title": "Image pairing and spread logic"}, {"id": "1068de50-7259-4d87-ad91-db2fbcf5ece2", "type": "concept", "title": "Book dummies and zines"}], "description": "Students explore the book, zine, and portfolio as photographic forms with pacing and structure."}, {"id": "572c6dd7-8a64-45e7-9b90-bfe24d13692d", "type": "subtopic", "title": "Text and exhibition", "children": [{"id": "9672cecf-152e-4f7b-af87-ea0396e46a4a", "type": "concept", "title": "Captions and extended text"}, {"id": "e953b845-8615-45a0-b427-f5ed54c0e334", "type": "concept", "title": "Artist statements"}, {"id": "9a629ead-a873-4ef3-9278-3114fae17091", "type": "concept", "title": "Print size and installation height"}, {"id": "f01bcfd1-0f60-4e2e-9d3d-36c4b249ed77", "type": "concept", "title": "Exhibition plans and technical checklists"}], "description": "The unit teaches how titles, captions, statements, scale, print surface, and wall sequence guide interpretation."}]}, {"id": "619f3a96-8111-4303-95d6-9366ee03e79e", "type": "topic", "title": "Ethics, Consent, Representation, Copyright, and Image Circulation", "description": "Photography has real effects on people and communities. This unit helps students make ethically informed decisions about consent, representation, manipulation, authorship, copyright, privacy, and circulation.", "children": [{"id": "1d9a2b95-1133-4a4d-9a48-d269dc7674a7", "type": "subtopic", "title": "Consent and representation", "children": [{"id": "a7f3e263-e08b-4835-861e-f53e2695fe76", "type": "concept", "title": "Informed consent and release forms"}, {"id": "606aaae8-9750-4282-9101-f8cf0f5b525a", "type": "concept", "title": "Vulnerability and power imbalance"}, {"id": "dcfb8453-2a48-4d08-8dc3-75a6aff0b4cf", "type": "concept", "title": "Community collaboration"}, {"id": "6d93e2dc-df46-4a8f-a6ec-6753f5543a3e", "type": "concept", "title": "Trauma, grief, and sensitive subjects"}], "description": "Students examine how images can dignify, exploit, stereotype, protect, reveal, or harm."}, {"id": "c20a3c24-8eda-4b76-8239-9e524d393c1c", "type": "subtopic", "title": "Truth, manipulation, and disclosure", "children": [{"id": "9a96d619-5327-4fca-a0de-905710bc09f7", "type": "concept", "title": "Staging and direction"}, {"id": "4a7662ec-70e6-4b8d-ac23-77ec6209fba5", "type": "concept", "title": "Retouching and compositing disclosure"}, {"id": "1b263d18-ca34-4b03-ae0d-137a29e85c7e", "type": "concept", "title": "Metadata and provenance"}, {"id": "6738bf03-c32f-4c01-aae5-5c2a84879072", "type": "concept", "title": "AI-generated or AI-altered images"}], "description": "Students learn how standards differ across art, documentary, journalism, advertising, and social media."}, {"id": "8a788885-b974-4092-8789-cbd108cd3e0f", "type": "subtopic", "title": "Copyright and circulation", "children": [{"id": "8c06a541-1e12-47f7-a4f7-5adfa84e1f65", "type": "concept", "title": "Copyright basics and releases"}, {"id": "596c74df-4d56-434b-9ed4-ddd1e39c804b", "type": "concept", "title": "Fair use and appropriation"}, {"id": "9a878d24-a146-4f88-8601-0cd2203dc197", "type": "concept", "title": "Creative Commons and licensing"}, {"id": "2b141470-d10e-4080-bb4f-56939826960b", "type": "concept", "title": "Online portfolios, social platforms, and image theft"}], "description": "The unit introduces creator rights, fair use, licensing, appropriation, platform terms, and portfolio publication."}]}, {"id": "8208b611-369a-49ac-9478-8228673b379c", "type": "topic", "title": "Capstone Portfolio: Critique, Editing, Printing, Exhibition, and Professional Practice", "description": "The capstone turns photographic study into a coherent body of work. Students produce, edit, sequence, print or publish, critique, revise, and present a portfolio with professional documentation.", "children": [{"id": "fa258cf0-2aaa-4111-80d8-975769a8955b", "type": "subtopic", "title": "Project proposal and production plan", "children": [{"id": "59c58ea1-9bbc-48ac-ab20-a552a8645418", "type": "concept", "title": "Concept statement"}, {"id": "e699e348-f61b-44d5-924a-5d42e3f61953", "type": "concept", "title": "Precedent research"}, {"id": "381b66be-0f94-4c7e-a91e-cf31011885b7", "type": "concept", "title": "Shot list or field plan"}, {"id": "df59985e-1f85-4016-8000-4f1ac0afdc9f", "type": "concept", "title": "Access, permissions, and logistics"}], "description": "Students define a photographic question, subject, visual strategy, timeline, and ethical approach."}, {"id": "4d131822-34b5-483b-88ed-e5be8bb48813", "type": "subtopic", "title": "Critique and revision", "children": [{"id": "c125cc21-3b01-417b-8c07-2772bdaaf545", "type": "concept", "title": "Contact-sheet review"}, {"id": "a76f9b00-9ff8-4f60-84bb-08fdbcf9745b", "type": "concept", "title": "Peer critique and faculty feedback"}, {"id": "7c67502a-5229-4732-9916-2231dddf6443", "type": "concept", "title": "Edit revisions and reshoots"}, {"id": "0152fcbe-abe4-4040-88c3-85b628c00a35", "type": "concept", "title": "Statement revision"}], "description": "Students learn to use critique as an editing instrument, revising both images and project structure."}, {"id": "dea3394c-6682-4de9-8c81-d0765c57ae4a", "type": "subtopic", "title": "Portfolio, print, and presentation", "children": [{"id": "30009f89-e5b7-4ad8-95fa-83185938c106", "type": "concept", "title": "Final sequencing"}, {"id": "4dad23e2-2bf4-484a-a956-0d45a2852372", "type": "concept", "title": "Print quality and output checks"}, {"id": "3f7f35f4-df3c-4917-b488-735b9961d7b6", "type": "concept", "title": "Portfolio website or PDF"}, {"id": "e2ac82d9-1a4c-4be7-88ec-8e677c769496", "type": "concept", "title": "Artist statement, captions, and archive handoff"}], "description": "The final step prepares work for exhibition, book, web portfolio, application, or client presentation."}]}], "dbBacked": true}$photjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'photography'
);

update public.learning_paths
set
  title = 'Photography',
  goal = 'Photography',
  summary = 'Photography is a studio course in image-making with light, cameras, digital workflow, history, critique, and visual storytelling. Students learn exposure, optics, composition, lighting, digital editing, black and white, color, portraiture, documentary practice, staged and conceptual photography, analog and alternative processes, sequencing, photobooks, exhibition design, ethics, copyright, and portfolio presentation. The course treats photography as both technical craft and a cultural form that shapes memory, evidence, identity, and public life.',
  data = $photjson${"slug": "photography", "title": "Photography", "description": "Photography is a studio course in image-making with light, cameras, digital workflow, history, critique, and visual storytelling. Students learn exposure, optics, composition, lighting, digital editing, black and white, color, portraiture, documentary practice, staged and conceptual photography, analog and alternative processes, sequencing, photobooks, exhibition design, ethics, copyright, and portfolio presentation. The course treats photography as both technical craft and a cultural form that shapes memory, evidence, identity, and public life.", "topics": [{"id": "bf7c9774-6af3-44ea-9f54-ebb82001912d", "type": "topic", "title": "Photographic Seeing, History, and Visual Culture", "description": "This opening unit treats photography as both technical craft and cultural language. Students learn how photographs make meaning through seeing, selection, framing, technology, circulation, and history.", "children": [{"id": "a9155988-cd16-49ae-b3fa-6072a069fb88", "type": "subtopic", "title": "Photography as a medium", "children": [{"id": "e6d73ac2-053a-4922-8672-46c12b5687dc", "type": "concept", "title": "Light as material"}, {"id": "38450abc-e8a0-4b60-800b-b14ff89fd2ee", "type": "concept", "title": "The camera as a choosing machine"}, {"id": "26f8613d-d950-4275-9350-be6ceffc4efd", "type": "concept", "title": "Evidence, memory, fiction, and document"}, {"id": "3e6678e8-a66e-4b78-8246-fd1b30269f2d", "type": "concept", "title": "Photography across art, journalism, science, commerce, and everyday life"}], "description": "Students learn what makes photography distinct: index, light, time, optics, apparatus, evidence, fiction, and point of view."}, {"id": "90d39b13-54b4-447a-af31-7b6119cf5bc0", "type": "subtopic", "title": "Histories of photography", "children": [{"id": "fb54c99c-18e7-42a1-b05c-79e6c1f03289", "type": "concept", "title": "Camera obscura and early processes"}, {"id": "27146f56-54b5-4835-9c30-d29fb68e9e27", "type": "concept", "title": "Pictorialism, modernism, and straight photography"}, {"id": "18f484f9-d3d4-4426-945e-ec5fc60c444f", "type": "concept", "title": "Documentary and social reform traditions"}, {"id": "eb68e69f-4486-446d-a911-769e67c6d02c", "type": "concept", "title": "Color, postmodernism, and contemporary lens-based practice"}], "description": "The goal is to situate current practice in a lineage from early processes through modernism, documentary, color, conceptual, digital, and networked image culture."}, {"id": "7e2c8197-b74a-48e7-95b3-8110bfa1aa5d", "type": "subtopic", "title": "Visual culture and image circulation", "children": [{"id": "0062ec6d-18c7-41a3-a420-e7345c10c893", "type": "concept", "title": "Photobooks and magazines"}, {"id": "0c8f0e11-dc68-4455-8a09-fd3a3661fa61", "type": "concept", "title": "Museums and archives"}, {"id": "73515d1f-105d-4f9e-a747-11aebc2e6d7d", "type": "concept", "title": "Social media and platforms"}, {"id": "dacac15c-cd55-45a0-892a-73634ddb87bc", "type": "concept", "title": "Image economies, attention, and reproduction"}], "description": "Students examine how photographs live in books, galleries, screens, archives, feeds, newspapers, ads, and family albums."}]}, {"id": "2f0bca49-dd7d-4957-ab2c-27efeafe3ee9", "type": "topic", "title": "Camera Systems, Exposure, Focus, and Optics", "description": "A strong photographer controls the camera deliberately. This unit builds fluency with exposure, focus, focal length, sensor or film behavior, lens choice, and image quality.", "children": [{"id": "80d662e2-c681-4653-8223-933f3a3a5c80", "type": "subtopic", "title": "Camera operation and exposure", "children": [{"id": "570f17bd-5a09-4562-8072-33f05a1a04b8", "type": "concept", "title": "Manual, aperture priority, and shutter priority modes"}, {"id": "fa7626e3-d23d-4d36-85d5-28b4193e503c", "type": "concept", "title": "Metering and exposure compensation"}, {"id": "f064e7d4-33fd-446e-a5a5-ccff9061ce2f", "type": "concept", "title": "Histograms and dynamic range"}, {"id": "abdb2e43-3225-4122-a215-fe5ef779f064", "type": "concept", "title": "Exposure bracketing and difficult light"}], "description": "Students learn how aperture, shutter speed, and ISO work together to shape brightness, motion, grain, depth of field, and intention."}, {"id": "b675b0bd-0991-4276-82f6-6bcf3f8f35c3", "type": "subtopic", "title": "Focus and lens behavior", "children": [{"id": "41d86825-ef46-438f-840f-e8d39aae022e", "type": "concept", "title": "Focal length and field of view"}, {"id": "6d2aa9c3-73c6-4495-bbea-099a557f18e2", "type": "concept", "title": "Depth of field and hyperfocal distance"}, {"id": "976b2ba1-de25-49a8-a1f2-7dc967eef3ca", "type": "concept", "title": "Autofocus modes and manual focus"}, {"id": "063d8bb6-37c7-4c4b-abd3-9070f2ca0a7a", "type": "concept", "title": "Lens distortion, compression, and perspective"}], "description": "The point is to understand how optics change spatial relationships, attention, and photographic voice."}, {"id": "34fd03ca-b3f8-4514-a7d4-db0dd5282b19", "type": "subtopic", "title": "Capture formats and technical quality", "children": [{"id": "5efa9528-e097-45ad-89ec-762887bfd75d", "type": "concept", "title": "RAW versus JPEG"}, {"id": "518f8728-961b-4de8-8727-0ab94de84d60", "type": "concept", "title": "Sensor size and aspect ratio"}, {"id": "bcacb31d-c08f-4140-8857-b77ea451cd4c", "type": "concept", "title": "Bit depth and compression"}, {"id": "84c420b8-f43d-4e90-986e-891e9424dfb9", "type": "concept", "title": "Tripods, stabilization, and sharpness"}], "description": "Students learn practical decisions that affect resolution, noise, color latitude, editing flexibility, and final output."}]}, {"id": "fa2f4bf3-e134-4012-98b7-aef062889cab", "type": "topic", "title": "Composition, Framing, Light, and Time", "description": "Composition is not a rulebook; it is the organization of attention. This unit helps students use frame, edge, timing, gesture, geometry, and light to make photographs that feel intentional.", "children": [{"id": "e4493081-628d-4438-84a6-6eb7b18d4166", "type": "subtopic", "title": "Frame and composition", "children": [{"id": "5ab1b73e-f2e0-4927-b4f5-b97064a7b47d", "type": "concept", "title": "Figure-ground relationships"}, {"id": "56132a0a-75c6-40c8-842f-5d18496ca219", "type": "concept", "title": "Balance, tension, rhythm, and repetition"}, {"id": "b370551f-bcd7-47eb-895e-90b0af7520b9", "type": "concept", "title": "Foreground, middle ground, and background"}, {"id": "6fc646c0-1584-4e4d-b7af-37f14bf3baae", "type": "concept", "title": "Cropping, aspect ratio, and edge control"}], "description": "Students learn how placement, scale, relation, edge, and empty space control how viewers move through an image."}, {"id": "92fc1edb-1a13-4f8e-a5ec-7f231f59941c", "type": "subtopic", "title": "Light as structure", "children": [{"id": "a440d199-e5e3-4fb4-a67b-0bff6531fec1", "type": "concept", "title": "Direction, quality, intensity, and color"}, {"id": "c142fbd6-95d0-42cd-8d00-6cccf79da132", "type": "concept", "title": "Backlight, sidelight, silhouette, and reflection"}, {"id": "e00cf411-0452-4843-9d5f-6c6b614b2896", "type": "concept", "title": "Natural light and available light"}, {"id": "18e2c158-26a4-4965-bb64-8b3cf561a005", "type": "concept", "title": "Shadow, contrast, and mood"}], "description": "Students study how light reveals, hides, dramatizes, flattens, separates, or transforms a subject."}, {"id": "f24d2cd5-48ee-409f-8863-5deb84bee066", "type": "subtopic", "title": "Time and decisive attention", "children": [{"id": "478a2dea-cf0c-45b9-aecb-d9d711b81fe0", "type": "concept", "title": "Freezing and blurring motion"}, {"id": "3a4fd319-17e8-476d-a278-f611b8cd57d2", "type": "concept", "title": "The decisive moment and its critiques"}, {"id": "ed2d1fb1-43e0-4356-8925-2b66824aba55", "type": "concept", "title": "Long exposure and accumulated time"}, {"id": "801249ce-f32f-4c1b-a3f8-f578cf5d18a6", "type": "concept", "title": "Sequence, repetition, and contact-sheet thinking"}], "description": "The unit connects shutter speed to gesture, duration, anticipation, and the ethics of choosing a moment."}]}, {"id": "e19711e9-e2d6-4018-b82e-b7bf5f577e60", "type": "topic", "title": "Digital Capture Workflow, File Management, and Color Management", "description": "A photography course teaches durable workflow habits. Students learn how to ingest, name, back up, edit, color-manage, and preserve image files without losing quality or context.", "children": [{"id": "28ada255-f9e4-41de-91f7-30501388d2a8", "type": "subtopic", "title": "Ingest, backup, and cataloging", "children": [{"id": "42fa0993-fad0-4b84-8a58-382998cab00c", "type": "concept", "title": "Folder structures and file naming"}, {"id": "75e17e14-a45f-47c0-88b5-a56e90f001d7", "type": "concept", "title": "Metadata, keywords, ratings, and captions"}, {"id": "123c46ae-905c-452b-a581-c16fb10d02a9", "type": "concept", "title": "3-2-1 backup strategy"}, {"id": "d3feb6d7-d30e-4736-aaa6-b0114471ff05", "type": "concept", "title": "Contact sheets and edit selects"}], "description": "Students learn a professional workflow that makes work findable, recoverable, and editable over time."}, {"id": "e091e78e-c5cb-47d0-b0e4-2a29f23b9193", "type": "subtopic", "title": "Color-managed workflow", "children": [{"id": "e25972cb-cf70-4215-ab40-c023c633a443", "type": "concept", "title": "White balance and profiles"}, {"id": "a32c747c-c237-47d7-8cdc-340a588b0e9b", "type": "concept", "title": "Monitor calibration concepts"}, {"id": "ff1eb37c-622e-45aa-8391-583747372386", "type": "concept", "title": "Soft proofing and output profiles"}, {"id": "5474df19-210b-4844-804b-280d3622e087", "type": "concept", "title": "Color spaces: sRGB, Adobe RGB, and ProPhoto RGB"}], "description": "Students learn why color shifts across cameras, monitors, printers, papers, and web platforms."}, {"id": "5bb93019-96bd-4a2a-8311-28f0a0385c7f", "type": "subtopic", "title": "Digital asset preservation", "children": [{"id": "8e1bf9a6-f9df-4c10-bb93-7635f4ac4b2d", "type": "concept", "title": "RAW files and sidecar data"}, {"id": "54fdc053-52be-452b-9353-b3da42e60369", "type": "concept", "title": "Non-destructive editing"}, {"id": "3346eed8-15ad-49b6-8ad6-53dbab05301e", "type": "concept", "title": "Versioning and exports"}, {"id": "5e16a07f-389f-4f63-9ed8-d3ec9b61c954", "type": "concept", "title": "Long-term storage and archive documentation"}], "description": "The goal is to treat photographs as an archive, not just exported images."}]}, {"id": "711bb8fb-72fe-4173-ba42-a58f8b79329f", "type": "topic", "title": "Lightroom, Photoshop, Editing, Retouching, and Output", "description": "Editing is part of photographic authorship. This unit teaches students to move from capture to resolved image through selection, tonal control, color correction, retouching, compositing awareness, and output.", "children": [{"id": "7e12bd87-e8dd-47c8-ad32-03a85e31e585", "type": "subtopic", "title": "Image selection and editing judgment", "children": [{"id": "84a85016-29ca-4581-9be7-c3bb6cd3c0ba", "type": "concept", "title": "Rating and culling systems"}, {"id": "fb278065-3b7a-4b5c-bb54-19dbd3051ef5", "type": "concept", "title": "Comparing similar frames"}, {"id": "272c3bc1-3240-41e0-979f-67ea3bc2a76b", "type": "concept", "title": "Edit for project coherence"}, {"id": "01edf555-2aa5-42e2-ab6e-028665d9168c", "type": "concept", "title": "Avoiding over-selection and attachment"}], "description": "Students learn to choose images by intention, sequence, formal strength, and ethical suitability rather than by technical perfection alone."}, {"id": "fe1bd552-6533-43c5-8bc4-d58effd46ac5", "type": "subtopic", "title": "Global and local adjustments", "children": [{"id": "0fe7da4c-d7a1-4066-bfe1-5113acd4899f", "type": "concept", "title": "Exposure, contrast, highlights, and shadows"}, {"id": "3f81a8fb-b7ba-4012-9fef-b94b2cc2d923", "type": "concept", "title": "Curves and tonal mapping"}, {"id": "9e5136a7-8a61-47f9-b205-582232b35362", "type": "concept", "title": "Masks, gradients, and local corrections"}, {"id": "58593876-c673-4e1f-9cae-3f5f249616c0", "type": "concept", "title": "Noise reduction and sharpening"}], "description": "Students practice making changes that support the photograph instead of calling attention to software."}, {"id": "426109fb-606f-4944-86ea-81dcd3eea568", "type": "subtopic", "title": "Retouching and output", "children": [{"id": "ef326a60-827e-4cd6-800a-71b3b910d300", "type": "concept", "title": "Dust spotting and cleanup"}, {"id": "7a75b441-f8c4-4300-bb85-38ca0849f0cd", "type": "concept", "title": "Skin and object retouching ethics"}, {"id": "6493d19c-be56-48eb-86bc-0d8ff840d263", "type": "concept", "title": "Export for print, web, portfolio, and projection"}, {"id": "72671a79-cdbb-461a-95dc-1d89e378daf2", "type": "concept", "title": "File formats and resolution requirements"}], "description": "The unit balances polish with credibility, teaching students what can be changed, what should be disclosed, and how files should leave the workspace."}]}, {"id": "fd726c69-99ab-4a54-801b-b5c472ddd1bf", "type": "topic", "title": "Black and White Photography and Tonal Craft", "description": "Black and white photography sharpens attention to light, tone, structure, texture, and form. Students learn how monochrome choices change meaning and how tonal craft supports visual clarity.", "children": [{"id": "e7ac51cf-a838-4f2b-b69c-71b6801de5db", "type": "subtopic", "title": "Seeing in tone", "children": [{"id": "00b9f04f-6afc-430b-a433-628df95cb11b", "type": "concept", "title": "Value scale and tonal separation"}, {"id": "a7af3ac7-a17a-4396-8b28-d7ced38bec20", "type": "concept", "title": "Texture and surface"}, {"id": "e5d5daaf-880e-46ce-8ce3-0030d5532032", "type": "concept", "title": "High-key and low-key imagery"}, {"id": "5ac71d9c-5587-4135-b3db-bc3e69928e8d", "type": "concept", "title": "Monochrome previsualization"}], "description": "Students train themselves to perceive luminance, contrast, texture, and shape without relying on color."}, {"id": "4ce09b24-15f7-4841-ba11-00958f09447b", "type": "subtopic", "title": "Black and white conversion", "children": [{"id": "ee84a9aa-4de2-4b5a-b4ac-2a08752a480b", "type": "concept", "title": "Channel mixing and color filters"}, {"id": "49616267-f34d-4d86-91e3-fff83fb35e2d", "type": "concept", "title": "Curves and contrast control"}, {"id": "2e81e4ae-39cb-4210-bea0-d6871a1c662e", "type": "concept", "title": "Dodging and burning"}, {"id": "5bde8cf9-d3ea-4018-a496-99293ab190d9", "type": "concept", "title": "Grain, clarity, and sharpening"}], "description": "Students learn how digital conversions are interpretive decisions, not automatic desaturation."}, {"id": "fcc202bd-6705-4c52-b6a4-1ef61f85b9d7", "type": "subtopic", "title": "Black and white traditions", "children": [{"id": "8596fbdc-d251-4872-a769-03df33994b54", "type": "concept", "title": "Documentary black and white"}, {"id": "03c3329e-025e-4860-9ef2-8c2f8cb0072a", "type": "concept", "title": "Modernist form and abstraction"}, {"id": "13ef5952-1922-405a-afbe-42974010ca39", "type": "concept", "title": "Portraiture and atmosphere"}, {"id": "d868d680-0ad1-4d82-b041-4c5d81a01fe0", "type": "concept", "title": "Archival and fine-art print references"}], "description": "The unit links tonal practice to major photographic histories and contemporary uses."}]}, {"id": "0cff92c7-216e-41e1-b321-31bd0525a2e8", "type": "topic", "title": "Color Photography, White Balance, and Color Meaning", "description": "Color is technical, perceptual, emotional, and cultural. This unit teaches students to control color accuracy when needed and use color subjectively when meaning calls for it.", "children": [{"id": "ca40827b-2a0f-49b3-9914-8446e371dbae", "type": "subtopic", "title": "White balance and color accuracy", "children": [{"id": "f9e8c8ce-5e9c-4b95-86ac-a64d95a2efb3", "type": "concept", "title": "Kelvin temperature"}, {"id": "2a6c9630-5331-4540-9ee5-941a694dab9d", "type": "concept", "title": "Tint and mixed lighting"}, {"id": "362e6e14-ecac-4cc9-9300-b6f2071e49dd", "type": "concept", "title": "Gray cards and custom white balance"}, {"id": "438b9f78-896e-4aaa-8c52-2831ca2a6877", "type": "concept", "title": "RAW correction and color profiles"}], "description": "Students learn how cameras interpret light color and how to correct or preserve color casts."}, {"id": "f9c4a986-c010-4f35-9e76-4c1b0dcfb341", "type": "subtopic", "title": "Color relationships and mood", "children": [{"id": "630aba33-e08c-46e2-8601-e8b5921dca23", "type": "concept", "title": "Hue, saturation, and luminosity"}, {"id": "56de0e33-b906-4df6-bdc2-0eab14738f5d", "type": "concept", "title": "Complementary and analogous color"}, {"id": "4000d326-b722-437c-a4e1-bf93e0e0de04", "type": "concept", "title": "Color contrast and harmony"}, {"id": "c7bf127e-d21d-4c4c-a6c5-0075fbedef9f", "type": "concept", "title": "Cultural meanings of color"}], "description": "Students develop a vocabulary for color as composition, symbolism, and atmosphere."}, {"id": "edb14695-55ed-4bbe-86bf-55583626a2e1", "type": "subtopic", "title": "Color in photographic history", "children": [{"id": "3d679d4b-7a08-4e3b-b288-336332ef025d", "type": "concept", "title": "Early color processes"}, {"id": "a0920de8-704c-4609-b09e-2ed7d02ffb9d", "type": "concept", "title": "New color photography"}, {"id": "0722d931-9d90-42d2-bdc5-fe395fe99053", "type": "concept", "title": "Color documentary"}, {"id": "d0e8a2b6-bd80-4a65-b8be-36dc2e9e9ef2", "type": "concept", "title": "Digital color grading and screen culture"}], "description": "The goal is to understand how color moved from commercial or amateur associations into art, documentary, and contemporary practice."}]}, {"id": "085d6454-3b8b-456e-ae36-844a876c456a", "type": "topic", "title": "Lighting: Natural, Studio, Flash, and Continuous", "description": "Lighting is the craft of shaping visibility. Students learn to read existing light and build controlled light for portraits, still lifes, products, interiors, and conceptual work.", "children": [{"id": "5b4af646-9b31-4aee-be85-99116a46dae0", "type": "subtopic", "title": "Natural and available light", "children": [{"id": "6e0cb01e-86c2-45b0-8595-0425c6624e29", "type": "concept", "title": "Golden hour, blue hour, and midday light"}, {"id": "40e1d1a6-4908-4139-a6a8-3470e5194b63", "type": "concept", "title": "Window light and reflectors"}, {"id": "b88ffed2-4295-4ad8-b18b-78d717427fcd", "type": "concept", "title": "Practical lights and mixed color"}, {"id": "c157a1a4-98af-41db-85df-839419b61803", "type": "concept", "title": "Location scouting for light"}], "description": "Students learn to work with daylight, ambient interiors, mixed sources, weather, time of day, and location constraints."}, {"id": "6e7b015a-52cd-4e83-b01c-5319e21bdde1", "type": "subtopic", "title": "Studio lighting fundamentals", "children": [{"id": "35963ca3-6dd0-4a46-9574-dd66bdbbe0a9", "type": "concept", "title": "Key, fill, rim, and background lights"}, {"id": "cca0cd4f-b984-4c06-89af-baf43310315c", "type": "concept", "title": "Softboxes, umbrellas, grids, flags, and reflectors"}, {"id": "be4a1514-3cb0-4066-965b-17752bd4dbf1", "type": "concept", "title": "Light ratios and inverse square law"}, {"id": "86d3442c-6dde-4696-8a27-ffd347bb829a", "type": "concept", "title": "Tethered capture and test frames"}], "description": "Students practice controlled lighting setups that make form, texture, mood, and separation legible."}, {"id": "8cf94584-f4f8-4d3d-bebc-0e7d29bfc4b8", "type": "subtopic", "title": "Flash and continuous systems", "children": [{"id": "84308690-b4a6-4879-ae28-339cf147d4c5", "type": "concept", "title": "On-camera and off-camera flash"}, {"id": "25f40313-81ae-4ba3-b9d1-53f702cb830c", "type": "concept", "title": "Sync speed and high-speed sync"}, {"id": "bafb0b85-4deb-4953-b3cc-917d1956fe37", "type": "concept", "title": "Modifiers and grip safety"}, {"id": "6971cec8-fe9e-4330-9fa8-8bc10b80ce04", "type": "concept", "title": "Lighting diagrams and repeatability"}], "description": "The unit compares speedlights, strobes, LEDs, and continuous setups so students can choose the right tool."}]}, {"id": "407f14b3-038a-41dc-ab11-8c42297c2aa1", "type": "topic", "title": "Portraiture, Studio Practice, and Subject Collaboration", "description": "Portraiture is a relationship as much as a picture. This unit focuses on trust, direction, lighting, gesture, environment, identity, consent, and collaboration with photographed people.", "children": [{"id": "f2ed92ba-8061-4524-ac01-88609e0853e9", "type": "subtopic", "title": "Portrait strategies", "children": [{"id": "0925cf17-a040-4a09-b61a-9512d9650bd3", "type": "concept", "title": "Expression, pose, and gesture"}, {"id": "0dd5be00-8dae-43b6-8aa3-89dd196ad4fa", "type": "concept", "title": "Background and environment"}, {"id": "9ec073bd-a0a5-410a-8c0e-01694dad52d3", "type": "concept", "title": "Gaze, address, and power"}, {"id": "fa82b6ce-15bf-498a-9c2f-d03d4fbb4df7", "type": "concept", "title": "Self-portraiture and identity"}], "description": "Students compare formal, environmental, candid, staged, self-portrait, and collaborative portrait approaches."}, {"id": "a37dcd2a-9ba6-4525-81ea-401729998777", "type": "subtopic", "title": "Working with subjects", "children": [{"id": "97329e00-608f-4dd6-ade1-2a591636c255", "type": "concept", "title": "Pre-shoot conversation"}, {"id": "a7fffb7b-bc32-43f1-bbe2-ab337dc579fa", "type": "concept", "title": "Model releases and expectations"}, {"id": "12ef1e2d-b52b-4224-96fd-2db2655cf794", "type": "concept", "title": "Directing without coercion"}, {"id": "3b42f971-3a06-4c62-a97c-669fa2d75e79", "type": "concept", "title": "Care, dignity, and representation"}], "description": "Students learn how communication, consent, scheduling, comfort, and direction affect both ethics and image quality."}, {"id": "2fb29abc-2748-45d8-8d2d-bc7062d2b036", "type": "subtopic", "title": "Studio portrait workflow", "children": [{"id": "bcf15dd3-735c-462e-930e-25260bda601e", "type": "concept", "title": "Lighting setups for faces and bodies"}, {"id": "90196dd0-8ecb-49d0-9a4a-5ecad615663e", "type": "concept", "title": "Lens choice and distance"}, {"id": "6ed49767-dd77-466a-bfd3-5687f0c0d015", "type": "concept", "title": "Tethering and review with subjects"}, {"id": "d80df667-19ac-4ea6-8a4e-859ee9addc7f", "type": "concept", "title": "Retouching boundaries"}], "description": "The goal is to combine technical control with human presence."}]}, {"id": "b53ec0f6-a22e-4f10-b14b-df4c8d63fb5c", "type": "topic", "title": "Documentary, Street, Photojournalism, and Visual Storytelling", "description": "Documentary photography asks students to make images about real people, places, events, and issues with care. This unit builds story structure, field practice, captions, editing, and ethical responsibility.", "children": [{"id": "46ad71ee-afb8-45db-b45c-25b25fe06acc", "type": "subtopic", "title": "Documentary approaches", "children": [{"id": "65c1fed7-f2f9-4068-8f50-c0653042a75a", "type": "concept", "title": "Observation and access"}, {"id": "3c2b74e0-ee77-40d0-b7ae-b86c9ade0637", "type": "concept", "title": "Photo essays and narrative arcs"}, {"id": "83f58337-d211-4ee3-8847-155d9701cbc6", "type": "concept", "title": "Caption and context"}, {"id": "d327989c-d2b9-4bcc-b139-1a7bafbe4e7b", "type": "concept", "title": "Long-term projects and immersion"}], "description": "Students learn that documentary ranges from observation to advocacy, essay, collaboration, and long-form research."}, {"id": "b1b93385-45ad-4a30-ae90-2efb68be0fa0", "type": "subtopic", "title": "Street and public-space photography", "children": [{"id": "c6cca3b5-5d85-4a5f-9655-24ad6f317c5f", "type": "concept", "title": "Anticipation and layering"}, {"id": "a3f99312-cca7-4511-b827-8261b4a04ce9", "type": "concept", "title": "Gesture and coincidence"}, {"id": "d5c08565-bd45-48d8-87bb-d110a54ddaee", "type": "concept", "title": "Public/private boundaries"}, {"id": "8d254c25-03af-4faf-a633-e4ae24d81e05", "type": "concept", "title": "Respectful field conduct"}], "description": "Students examine spontaneity, publicness, law, safety, consent, and the social behavior of photographing in public."}, {"id": "636d801c-76f3-48ba-a426-951cde6f450c", "type": "subtopic", "title": "Photojournalism standards", "children": [{"id": "2fd5b4c1-fdd8-4600-925c-8b44ba76238f", "type": "concept", "title": "News values and visual evidence"}, {"id": "f600489e-d2fe-458e-9bae-5ee1f958837d", "type": "concept", "title": "Caption writing and metadata"}, {"id": "df42caec-e0c9-4003-9a7e-f517a2a9b92f", "type": "concept", "title": "Editorial ethics and staging limits"}, {"id": "9985f223-d2fa-42ad-a069-75d8aa1f4975", "type": "concept", "title": "Trauma-aware reporting and minimizing harm"}], "description": "The unit introduces verification, caption accuracy, manipulation limits, deadlines, and public trust."}]}, {"id": "52a460ad-24b3-4ca1-8340-105232e93851", "type": "topic", "title": "Constructed, Conceptual, Staged, and Experimental Photography", "description": "Photography is not limited to capture. Students explore images built through staging, performance, intervention, appropriation, abstraction, process, and conceptual systems.", "children": [{"id": "ea10da0b-a84b-466d-bfc3-68da582765a1", "type": "subtopic", "title": "Staged and constructed images", "children": [{"id": "91605668-f0bc-456a-9be6-ca2a41803c2e", "type": "concept", "title": "Tableau and mise-en-scene"}, {"id": "4fc764c1-8e0e-4be4-bad0-56a1212b5cc4", "type": "concept", "title": "Performance for the camera"}, {"id": "6720d1a8-1223-4336-b23d-ee9a52ba32c3", "type": "concept", "title": "Still life and constructed scenes"}, {"id": "3183d9ce-f255-474b-af26-6ab08a904aef", "type": "concept", "title": "Fiction, fantasy, and ambiguity"}], "description": "Students learn how props, sets, performance, lighting, costume, and narrative ambiguity can create photographic worlds."}, {"id": "a7676089-d793-489f-a211-cea5bbf17c61", "type": "subtopic", "title": "Conceptual and process-based work", "children": [{"id": "2e000854-0e9f-4290-b109-dfcd199b0229", "type": "concept", "title": "Typology and seriality"}, {"id": "a7870c5e-9ec0-4f7f-b56f-17e9a0e0fc10", "type": "concept", "title": "Instruction-based work"}, {"id": "cf0480b8-c225-4c26-8682-a93b7db83df5", "type": "concept", "title": "Chance and constraint"}, {"id": "b79fce18-2b38-471e-a085-58728e09caaa", "type": "concept", "title": "Photography as idea and evidence"}], "description": "Students explore photographic projects driven by rules, systems, typologies, archives, or repeated actions."}, {"id": "0d014ec7-3b0d-4673-8a3e-835061d05fea", "type": "subtopic", "title": "Experimental image-making", "children": [{"id": "2d7fe260-e97d-450f-bec7-e1423de52166", "type": "concept", "title": "Scanography and photocollage"}, {"id": "23e5ad7d-bdc5-48f4-be0d-cb4e81fd9e86", "type": "concept", "title": "Glitch, abstraction, and distortion"}, {"id": "3ad37227-ddc0-4868-86a0-0ca662e0fb6f", "type": "concept", "title": "Projection and rephotography"}, {"id": "8f1e7edf-531f-4e3c-9b34-284eff55e21f", "type": "concept", "title": "Mixed media and installation"}], "description": "The unit invites risk with camera-less, hybrid, digital, and material methods."}]}, {"id": "a4533db6-ee81-4080-b8a8-aa15aba256d3", "type": "topic", "title": "Analog Processes, Darkroom, Alternative Processes, and Materiality", "description": "Analog and alternative processes teach students that photographs are objects, chemicals, surfaces, and time-based traces. Even digital photographers gain deeper craft from understanding material process.", "children": [{"id": "d21131ed-fa42-4d33-a58e-a58af0704443", "type": "subtopic", "title": "Film and darkroom overview", "children": [{"id": "f9409688-a878-4d81-93eb-d6a929c8632a", "type": "concept", "title": "Film stocks and formats"}, {"id": "9aa42c83-324c-4ca4-a357-b8586b20dbbf", "type": "concept", "title": "Developing, contact sheets, and negatives"}, {"id": "43dc900a-0143-433e-bc4b-b50e3e0d1e44", "type": "concept", "title": "Enlarger basics"}, {"id": "569bb842-05d0-400d-af55-9d0cd698a22d", "type": "concept", "title": "Dodging, burning, and test strips"}], "description": "Students learn the conceptual and practical foundations of film exposure, development, contact sheets, enlarging, and print evaluation."}, {"id": "b849741a-84f3-41e3-ac1d-a4e323fe5671", "type": "subtopic", "title": "Alternative and historical processes", "children": [{"id": "37f89702-d5ae-4937-a43b-177d92f2f032", "type": "concept", "title": "Cyanotype and photograms"}, {"id": "7bf9eed6-5da0-49ae-99ae-724559b4fe9f", "type": "concept", "title": "Pinhole photography"}, {"id": "9e62aa2c-7583-43cb-8450-fddb481e5ccd", "type": "concept", "title": "Salt, albumen, platinum, and gum overview"}, {"id": "235f5986-4b89-4fec-88a6-617cf0f36258", "type": "concept", "title": "Process variables and experimentation"}], "description": "Students explore hand-made photographic surfaces and the history of image technologies."}, {"id": "bcfba9a4-b303-485c-baff-4efb22a325d1", "type": "subtopic", "title": "Photograph as object", "children": [{"id": "fc31091d-b109-414a-ad9b-1adf699b21d7", "type": "concept", "title": "Paper types and surface"}, {"id": "62c1d104-1030-44ec-bfb1-790e0221a435", "type": "concept", "title": "Editioning and handling"}, {"id": "dd77a0a9-bdd1-436c-aa0f-d50715c7ba33", "type": "concept", "title": "Mounting and framing"}, {"id": "fe417e8b-c6c7-46cf-a230-7890d5929389", "type": "concept", "title": "Object care and storage"}], "description": "The goal is to think beyond screen images toward paper, scale, surface, edition, installation, and conservation."}]}, {"id": "2ae127a7-1fa1-4bef-aed6-2a3d15a96766", "type": "topic", "title": "Sequencing, Series, Photobooks, Text, and Exhibition Design", "description": "Photographs often become powerful through relation: sequence, rhythm, repetition, edit, scale, caption, and installation. This unit teaches students to make bodies of work rather than isolated good images.", "children": [{"id": "ca5bfdae-a591-42a9-bd6f-51e94461e763", "type": "subtopic", "title": "Series development", "children": [{"id": "5cfd71eb-6e30-481e-916e-0963e0db3b47", "type": "concept", "title": "Project statements and constraints"}, {"id": "95afa64a-5652-4362-8ef5-98d04acebd7b", "type": "concept", "title": "Typology and variation"}, {"id": "38445ac2-b251-42e0-bf6e-0e1f05d4e929", "type": "concept", "title": "Edit for coherence and surprise"}, {"id": "1d461968-cd45-45ec-b8fb-f7b7efc49ba7", "type": "concept", "title": "Critique of gaps and redundancies"}], "description": "Students learn how projects cohere through subject, method, visual language, concept, and edit."}, {"id": "d322c698-302d-4870-93b4-d27e4db5d418", "type": "subtopic", "title": "Sequencing and photobooks", "children": [{"id": "760a215c-53f2-4a32-8c88-8bd4cabe514a", "type": "concept", "title": "Opening and closing images"}, {"id": "8b3eaf99-ec32-4755-8ebc-1e6679658469", "type": "concept", "title": "Rhythm, pause, and transition"}, {"id": "5d48d35b-e92d-447e-9628-40c63916075c", "type": "concept", "title": "Image pairing and spread logic"}, {"id": "1068de50-7259-4d87-ad91-db2fbcf5ece2", "type": "concept", "title": "Book dummies and zines"}], "description": "Students explore the book, zine, and portfolio as photographic forms with pacing and structure."}, {"id": "572c6dd7-8a64-45e7-9b90-bfe24d13692d", "type": "subtopic", "title": "Text and exhibition", "children": [{"id": "9672cecf-152e-4f7b-af87-ea0396e46a4a", "type": "concept", "title": "Captions and extended text"}, {"id": "e953b845-8615-45a0-b427-f5ed54c0e334", "type": "concept", "title": "Artist statements"}, {"id": "9a629ead-a873-4ef3-9278-3114fae17091", "type": "concept", "title": "Print size and installation height"}, {"id": "f01bcfd1-0f60-4e2e-9d3d-36c4b249ed77", "type": "concept", "title": "Exhibition plans and technical checklists"}], "description": "The unit teaches how titles, captions, statements, scale, print surface, and wall sequence guide interpretation."}]}, {"id": "619f3a96-8111-4303-95d6-9366ee03e79e", "type": "topic", "title": "Ethics, Consent, Representation, Copyright, and Image Circulation", "description": "Photography has real effects on people and communities. This unit helps students make ethically informed decisions about consent, representation, manipulation, authorship, copyright, privacy, and circulation.", "children": [{"id": "1d9a2b95-1133-4a4d-9a48-d269dc7674a7", "type": "subtopic", "title": "Consent and representation", "children": [{"id": "a7f3e263-e08b-4835-861e-f53e2695fe76", "type": "concept", "title": "Informed consent and release forms"}, {"id": "606aaae8-9750-4282-9101-f8cf0f5b525a", "type": "concept", "title": "Vulnerability and power imbalance"}, {"id": "dcfb8453-2a48-4d08-8dc3-75a6aff0b4cf", "type": "concept", "title": "Community collaboration"}, {"id": "6d93e2dc-df46-4a8f-a6ec-6753f5543a3e", "type": "concept", "title": "Trauma, grief, and sensitive subjects"}], "description": "Students examine how images can dignify, exploit, stereotype, protect, reveal, or harm."}, {"id": "c20a3c24-8eda-4b76-8239-9e524d393c1c", "type": "subtopic", "title": "Truth, manipulation, and disclosure", "children": [{"id": "9a96d619-5327-4fca-a0de-905710bc09f7", "type": "concept", "title": "Staging and direction"}, {"id": "4a7662ec-70e6-4b8d-ac23-77ec6209fba5", "type": "concept", "title": "Retouching and compositing disclosure"}, {"id": "1b263d18-ca34-4b03-ae0d-137a29e85c7e", "type": "concept", "title": "Metadata and provenance"}, {"id": "6738bf03-c32f-4c01-aae5-5c2a84879072", "type": "concept", "title": "AI-generated or AI-altered images"}], "description": "Students learn how standards differ across art, documentary, journalism, advertising, and social media."}, {"id": "8a788885-b974-4092-8789-cbd108cd3e0f", "type": "subtopic", "title": "Copyright and circulation", "children": [{"id": "8c06a541-1e12-47f7-a4f7-5adfa84e1f65", "type": "concept", "title": "Copyright basics and releases"}, {"id": "596c74df-4d56-434b-9ed4-ddd1e39c804b", "type": "concept", "title": "Fair use and appropriation"}, {"id": "9a878d24-a146-4f88-8601-0cd2203dc197", "type": "concept", "title": "Creative Commons and licensing"}, {"id": "2b141470-d10e-4080-bb4f-56939826960b", "type": "concept", "title": "Online portfolios, social platforms, and image theft"}], "description": "The unit introduces creator rights, fair use, licensing, appropriation, platform terms, and portfolio publication."}]}, {"id": "8208b611-369a-49ac-9478-8228673b379c", "type": "topic", "title": "Capstone Portfolio: Critique, Editing, Printing, Exhibition, and Professional Practice", "description": "The capstone turns photographic study into a coherent body of work. Students produce, edit, sequence, print or publish, critique, revise, and present a portfolio with professional documentation.", "children": [{"id": "fa258cf0-2aaa-4111-80d8-975769a8955b", "type": "subtopic", "title": "Project proposal and production plan", "children": [{"id": "59c58ea1-9bbc-48ac-ab20-a552a8645418", "type": "concept", "title": "Concept statement"}, {"id": "e699e348-f61b-44d5-924a-5d42e3f61953", "type": "concept", "title": "Precedent research"}, {"id": "381b66be-0f94-4c7e-a91e-cf31011885b7", "type": "concept", "title": "Shot list or field plan"}, {"id": "df59985e-1f85-4016-8000-4f1ac0afdc9f", "type": "concept", "title": "Access, permissions, and logistics"}], "description": "Students define a photographic question, subject, visual strategy, timeline, and ethical approach."}, {"id": "4d131822-34b5-483b-88ed-e5be8bb48813", "type": "subtopic", "title": "Critique and revision", "children": [{"id": "c125cc21-3b01-417b-8c07-2772bdaaf545", "type": "concept", "title": "Contact-sheet review"}, {"id": "a76f9b00-9ff8-4f60-84bb-08fdbcf9745b", "type": "concept", "title": "Peer critique and faculty feedback"}, {"id": "7c67502a-5229-4732-9916-2231dddf6443", "type": "concept", "title": "Edit revisions and reshoots"}, {"id": "0152fcbe-abe4-4040-88c3-85b628c00a35", "type": "concept", "title": "Statement revision"}], "description": "Students learn to use critique as an editing instrument, revising both images and project structure."}, {"id": "dea3394c-6682-4de9-8c81-d0765c57ae4a", "type": "subtopic", "title": "Portfolio, print, and presentation", "children": [{"id": "30009f89-e5b7-4ad8-95fa-83185938c106", "type": "concept", "title": "Final sequencing"}, {"id": "4dad23e2-2bf4-484a-a956-0d45a2852372", "type": "concept", "title": "Print quality and output checks"}, {"id": "3f7f35f4-df3c-4917-b488-735b9961d7b6", "type": "concept", "title": "Portfolio website or PDF"}, {"id": "e2ac82d9-1a4c-4be7-88ec-8e677c769496", "type": "concept", "title": "Artist statement, captions, and archive handoff"}], "description": "The final step prepares work for exhibition, book, web portfolio, application, or client presentation."}]}], "dbBacked": true}$photjson$::jsonb,
