values
  ('bf7c9774-6af3-44ea-9f54-ebb82001912d', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', null, 'topic'::public.curated_course_node_type, 'Photographic Seeing, History, and Visual Culture', 'This opening unit treats photography as both technical craft and cultural language. Students learn how photographs make meaning through seeing, selection, framing, technology, circulation, and history.', 0),
  ('a9155988-cd16-49ae-b3fa-6072a069fb88', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'bf7c9774-6af3-44ea-9f54-ebb82001912d', 'subtopic'::public.curated_course_node_type, 'Photography as a medium', 'Students learn what makes photography distinct: index, light, time, optics, apparatus, evidence, fiction, and point of view.', 0),
  ('e6d73ac2-053a-4922-8672-46c12b5687dc', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'a9155988-cd16-49ae-b3fa-6072a069fb88', 'concept'::public.curated_course_node_type, 'Light as material', null, 0),
  ('38450abc-e8a0-4b60-800b-b14ff89fd2ee', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'a9155988-cd16-49ae-b3fa-6072a069fb88', 'concept'::public.curated_course_node_type, 'The camera as a choosing machine', null, 1),
  ('26f8613d-d950-4275-9350-be6ceffc4efd', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'a9155988-cd16-49ae-b3fa-6072a069fb88', 'concept'::public.curated_course_node_type, 'Evidence, memory, fiction, and document', null, 2),
  ('3e6678e8-a66e-4b78-8246-fd1b30269f2d', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'a9155988-cd16-49ae-b3fa-6072a069fb88', 'concept'::public.curated_course_node_type, 'Photography across art, journalism, science, commerce, and everyday life', null, 3),
  ('90d39b13-54b4-447a-af31-7b6119cf5bc0', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'bf7c9774-6af3-44ea-9f54-ebb82001912d', 'subtopic'::public.curated_course_node_type, 'Histories of photography', 'The goal is to situate current practice in a lineage from early processes through modernism, documentary, color, conceptual, digital, and networked image culture.', 1),
  ('fb54c99c-18e7-42a1-b05c-79e6c1f03289', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '90d39b13-54b4-447a-af31-7b6119cf5bc0', 'concept'::public.curated_course_node_type, 'Camera obscura and early processes', null, 0),
  ('27146f56-54b5-4835-9c30-d29fb68e9e27', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '90d39b13-54b4-447a-af31-7b6119cf5bc0', 'concept'::public.curated_course_node_type, 'Pictorialism, modernism, and straight photography', null, 1),
  ('18f484f9-d3d4-4426-945e-ec5fc60c444f', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '90d39b13-54b4-447a-af31-7b6119cf5bc0', 'concept'::public.curated_course_node_type, 'Documentary and social reform traditions', null, 2),
  ('eb68e69f-4486-446d-a911-769e67c6d02c', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '90d39b13-54b4-447a-af31-7b6119cf5bc0', 'concept'::public.curated_course_node_type, 'Color, postmodernism, and contemporary lens-based practice', null, 3),
  ('7e2c8197-b74a-48e7-95b3-8110bfa1aa5d', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'bf7c9774-6af3-44ea-9f54-ebb82001912d', 'subtopic'::public.curated_course_node_type, 'Visual culture and image circulation', 'Students examine how photographs live in books, galleries, screens, archives, feeds, newspapers, ads, and family albums.', 2),
  ('0062ec6d-18c7-41a3-a420-e7345c10c893', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '7e2c8197-b74a-48e7-95b3-8110bfa1aa5d', 'concept'::public.curated_course_node_type, 'Photobooks and magazines', null, 0),
  ('0c8f0e11-dc68-4455-8a09-fd3a3661fa61', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '7e2c8197-b74a-48e7-95b3-8110bfa1aa5d', 'concept'::public.curated_course_node_type, 'Museums and archives', null, 1),
  ('73515d1f-105d-4f9e-a747-11aebc2e6d7d', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '7e2c8197-b74a-48e7-95b3-8110bfa1aa5d', 'concept'::public.curated_course_node_type, 'Social media and platforms', null, 2),
  ('dacac15c-cd55-45a0-892a-73634ddb87bc', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '7e2c8197-b74a-48e7-95b3-8110bfa1aa5d', 'concept'::public.curated_course_node_type, 'Image economies, attention, and reproduction', null, 3),
  ('2f0bca49-dd7d-4957-ab2c-27efeafe3ee9', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', null, 'topic'::public.curated_course_node_type, 'Camera Systems, Exposure, Focus, and Optics', 'A strong photographer controls the camera deliberately. This unit builds fluency with exposure, focus, focal length, sensor or film behavior, lens choice, and image quality.', 1),
  ('80d662e2-c681-4653-8223-933f3a3a5c80', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '2f0bca49-dd7d-4957-ab2c-27efeafe3ee9', 'subtopic'::public.curated_course_node_type, 'Camera operation and exposure', 'Students learn how aperture, shutter speed, and ISO work together to shape brightness, motion, grain, depth of field, and intention.', 0),
  ('570f17bd-5a09-4562-8072-33f05a1a04b8', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '80d662e2-c681-4653-8223-933f3a3a5c80', 'concept'::public.curated_course_node_type, 'Manual, aperture priority, and shutter priority modes', null, 0),
  ('fa7626e3-d23d-4d36-85d5-28b4193e503c', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '80d662e2-c681-4653-8223-933f3a3a5c80', 'concept'::public.curated_course_node_type, 'Metering and exposure compensation', null, 1),
  ('f064e7d4-33fd-446e-a5a5-ccff9061ce2f', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '80d662e2-c681-4653-8223-933f3a3a5c80', 'concept'::public.curated_course_node_type, 'Histograms and dynamic range', null, 2),
  ('abdb2e43-3225-4122-a215-fe5ef779f064', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '80d662e2-c681-4653-8223-933f3a3a5c80', 'concept'::public.curated_course_node_type, 'Exposure bracketing and difficult light', null, 3),
  ('b675b0bd-0991-4276-82f6-6bcf3f8f35c3', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '2f0bca49-dd7d-4957-ab2c-27efeafe3ee9', 'subtopic'::public.curated_course_node_type, 'Focus and lens behavior', 'The point is to understand how optics change spatial relationships, attention, and photographic voice.', 1),
  ('41d86825-ef46-438f-840f-e8d39aae022e', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'b675b0bd-0991-4276-82f6-6bcf3f8f35c3', 'concept'::public.curated_course_node_type, 'Focal length and field of view', null, 0),
  ('6d2aa9c3-73c6-4495-bbea-099a557f18e2', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'b675b0bd-0991-4276-82f6-6bcf3f8f35c3', 'concept'::public.curated_course_node_type, 'Depth of field and hyperfocal distance', null, 1),
  ('976b2ba1-de25-49a8-a1f2-7dc967eef3ca', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'b675b0bd-0991-4276-82f6-6bcf3f8f35c3', 'concept'::public.curated_course_node_type, 'Autofocus modes and manual focus', null, 2),
  ('063d8bb6-37c7-4c4b-abd3-9070f2ca0a7a', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'b675b0bd-0991-4276-82f6-6bcf3f8f35c3', 'concept'::public.curated_course_node_type, 'Lens distortion, compression, and perspective', null, 3),
  ('34fd03ca-b3f8-4514-a7d4-db0dd5282b19', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '2f0bca49-dd7d-4957-ab2c-27efeafe3ee9', 'subtopic'::public.curated_course_node_type, 'Capture formats and technical quality', 'Students learn practical decisions that affect resolution, noise, color latitude, editing flexibility, and final output.', 2),
  ('5efa9528-e097-45ad-89ec-762887bfd75d', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '34fd03ca-b3f8-4514-a7d4-db0dd5282b19', 'concept'::public.curated_course_node_type, 'RAW versus JPEG', null, 0),
  ('518f8728-961b-4de8-8727-0ab94de84d60', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '34fd03ca-b3f8-4514-a7d4-db0dd5282b19', 'concept'::public.curated_course_node_type, 'Sensor size and aspect ratio', null, 1),
  ('bcacb31d-c08f-4140-8857-b77ea451cd4c', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '34fd03ca-b3f8-4514-a7d4-db0dd5282b19', 'concept'::public.curated_course_node_type, 'Bit depth and compression', null, 2),
  ('84c420b8-f43d-4e90-986e-891e9424dfb9', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '34fd03ca-b3f8-4514-a7d4-db0dd5282b19', 'concept'::public.curated_course_node_type, 'Tripods, stabilization, and sharpness', null, 3),
  ('fa2f4bf3-e134-4012-98b7-aef062889cab', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', null, 'topic'::public.curated_course_node_type, 'Composition, Framing, Light, and Time', 'Composition is not a rulebook; it is the organization of attention. This unit helps students use frame, edge, timing, gesture, geometry, and light to make photographs that feel intentional.', 2),
  ('e4493081-628d-4438-84a6-6eb7b18d4166', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'fa2f4bf3-e134-4012-98b7-aef062889cab', 'subtopic'::public.curated_course_node_type, 'Frame and composition', 'Students learn how placement, scale, relation, edge, and empty space control how viewers move through an image.', 0),
  ('5ab1b73e-f2e0-4927-b4f5-b97064a7b47d', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'e4493081-628d-4438-84a6-6eb7b18d4166', 'concept'::public.curated_course_node_type, 'Figure-ground relationships', null, 0),
  ('56132a0a-75c6-40c8-842f-5d18496ca219', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'e4493081-628d-4438-84a6-6eb7b18d4166', 'concept'::public.curated_course_node_type, 'Balance, tension, rhythm, and repetition', null, 1),
  ('b370551f-bcd7-47eb-895e-90b0af7520b9', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'e4493081-628d-4438-84a6-6eb7b18d4166', 'concept'::public.curated_course_node_type, 'Foreground, middle ground, and background', null, 2),
  ('6fc646c0-1584-4e4d-b7af-37f14bf3baae', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'e4493081-628d-4438-84a6-6eb7b18d4166', 'concept'::public.curated_course_node_type, 'Cropping, aspect ratio, and edge control', null, 3),
  ('92fc1edb-1a13-4f8e-a5ec-7f231f59941c', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'fa2f4bf3-e134-4012-98b7-aef062889cab', 'subtopic'::public.curated_course_node_type, 'Light as structure', 'Students study how light reveals, hides, dramatizes, flattens, separates, or transforms a subject.', 1),
  ('a440d199-e5e3-4fb4-a67b-0bff6531fec1', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '92fc1edb-1a13-4f8e-a5ec-7f231f59941c', 'concept'::public.curated_course_node_type, 'Direction, quality, intensity, and color', null, 0);
