  ('e19711e9-e2d6-4018-b82e-b7bf5f577e60', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', null, 'topic'::public.curated_course_node_type, 'Digital Capture Workflow, File Management, and Color Management', 'A photography course teaches durable workflow habits. Students learn how to ingest, name, back up, edit, color-manage, and preserve image files without losing quality or context.', 3),
