  ('5e16a07f-389f-4f63-9ed8-d3ec9b61c954', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '5bb93019-96bd-4a2a-8311-28f0a0385c7f', 'concept'::public.curated_course_node_type, 'Long-term storage and archive documentation', null, 3),
  ('711bb8fb-72fe-4173-ba42-a58f8b79329f', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', null, 'topic'::public.curated_course_node_type, 'Lightroom, Photoshop, Editing, Retouching, and Output', 'Editing is part of photographic authorship. This unit teaches students to move from capture to resolved image through selection, tonal control, color correction, retouching, compositing awareness, and output.', 4),
  ('7e12bd87-e8dd-47c8-ad32-03a85e31e585', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '711bb8fb-72fe-4173-ba42-a58f8b79329f', 'subtopic'::public.curated_course_node_type, 'Image selection and editing judgment', 'Students learn to choose images by intention, sequence, formal strength, and ethical suitability rather than by technical perfection alone.', 0),
  ('84a85016-29ca-4581-9be7-c3bb6cd3c0ba', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '7e12bd87-e8dd-47c8-ad32-03a85e31e585', 'concept'::public.curated_course_node_type, 'Rating and culling systems', null, 0),
  ('fb278065-3b7a-4b5c-bb54-19dbd3051ef5', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '7e12bd87-e8dd-47c8-ad32-03a85e31e585', 'concept'::public.curated_course_node_type, 'Comparing similar frames', null, 1),
  ('272c3bc1-3240-41e0-979f-67ea3bc2a76b', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '7e12bd87-e8dd-47c8-ad32-03a85e31e585', 'concept'::public.curated_course_node_type, 'Edit for project coherence', null, 2),
  ('01edf555-2aa5-42e2-ab6e-028665d9168c', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '7e12bd87-e8dd-47c8-ad32-03a85e31e585', 'concept'::public.curated_course_node_type, 'Avoiding over-selection and attachment', null, 3),
  ('fe1bd552-6533-43c5-8bc4-d58effd46ac5', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '711bb8fb-72fe-4173-ba42-a58f8b79329f', 'subtopic'::public.curated_course_node_type, 'Global and local adjustments', 'Students practice making changes that support the photograph instead of calling attention to software.', 1),
  ('0fe7da4c-d7a1-4066-bfe1-5113acd4899f', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'fe1bd552-6533-43c5-8bc4-d58effd46ac5', 'concept'::public.curated_course_node_type, 'Exposure, contrast, highlights, and shadows', null, 0),
  ('3f81a8fb-b7ba-4012-9fef-b94b2cc2d923', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'fe1bd552-6533-43c5-8bc4-d58effd46ac5', 'concept'::public.curated_course_node_type, 'Curves and tonal mapping', null, 1),
  ('9e5136a7-8a61-47f9-b205-582232b35362', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'fe1bd552-6533-43c5-8bc4-d58effd46ac5', 'concept'::public.curated_course_node_type, 'Masks, gradients, and local corrections', null, 2),
  ('58593876-c673-4e1f-9cae-3f5f249616c0', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'fe1bd552-6533-43c5-8bc4-d58effd46ac5', 'concept'::public.curated_course_node_type, 'Noise reduction and sharpening', null, 3),
  ('426109fb-606f-4944-86ea-81dcd3eea568', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '711bb8fb-72fe-4173-ba42-a58f8b79329f', 'subtopic'::public.curated_course_node_type, 'Retouching and output', 'The unit balances polish with credibility, teaching students what can be changed, what should be disclosed, and how files should leave the workspace.', 2),
  ('ef326a60-827e-4cd6-800a-71b3b910d300', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '426109fb-606f-4944-86ea-81dcd3eea568', 'concept'::public.curated_course_node_type, 'Dust spotting and cleanup', null, 0),
  ('7a75b441-f8c4-4300-bb85-38ca0849f0cd', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '426109fb-606f-4944-86ea-81dcd3eea568', 'concept'::public.curated_course_node_type, 'Skin and object retouching ethics', null, 1),
  ('6493d19c-be56-48eb-86bc-0d8ff840d263', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '426109fb-606f-4944-86ea-81dcd3eea568', 'concept'::public.curated_course_node_type, 'Export for print, web, portfolio, and projection', null, 2),
  ('72671a79-cdbb-461a-95dc-1d89e378daf2', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '426109fb-606f-4944-86ea-81dcd3eea568', 'concept'::public.curated_course_node_type, 'File formats and resolution requirements', null, 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('fd726c69-99ab-4a54-801b-b5c472ddd1bf', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', null, 'topic'::public.curated_course_node_type, 'Black and White Photography and Tonal Craft', 'Black and white photography sharpens attention to light, tone, structure, texture, and form. Students learn how monochrome choices change meaning and how tonal craft supports visual clarity.', 5),
  ('e7ac51cf-a838-4f2b-b69c-71b6801de5db', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'fd726c69-99ab-4a54-801b-b5c472ddd1bf', 'subtopic'::public.curated_course_node_type, 'Seeing in tone', 'Students train themselves to perceive luminance, contrast, texture, and shape without relying on color.', 0),
  ('00b9f04f-6afc-430b-a433-628df95cb11b', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'e7ac51cf-a838-4f2b-b69c-71b6801de5db', 'concept'::public.curated_course_node_type, 'Value scale and tonal separation', null, 0),
  ('a7af3ac7-a17a-4396-8b28-d7ced38bec20', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'e7ac51cf-a838-4f2b-b69c-71b6801de5db', 'concept'::public.curated_course_node_type, 'Texture and surface', null, 1),
  ('e5d5daaf-880e-46ce-8ce3-0030d5532032', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'e7ac51cf-a838-4f2b-b69c-71b6801de5db', 'concept'::public.curated_course_node_type, 'High-key and low-key imagery', null, 2),
  ('5ac71d9c-5587-4135-b3db-bc3e69928e8d', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'e7ac51cf-a838-4f2b-b69c-71b6801de5db', 'concept'::public.curated_course_node_type, 'Monochrome previsualization', null, 3),
  ('4ce09b24-15f7-4841-ba11-00958f09447b', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'fd726c69-99ab-4a54-801b-b5c472ddd1bf', 'subtopic'::public.curated_course_node_type, 'Black and white conversion', 'Students learn how digital conversions are interpretive decisions, not automatic desaturation.', 1),
  ('ee84a9aa-4de2-4b5a-b4ac-2a08752a480b', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '4ce09b24-15f7-4841-ba11-00958f09447b', 'concept'::public.curated_course_node_type, 'Channel mixing and color filters', null, 0),
  ('49616267-f34d-4d86-91e3-fff83fb35e2d', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '4ce09b24-15f7-4841-ba11-00958f09447b', 'concept'::public.curated_course_node_type, 'Curves and contrast control', null, 1),
  ('2e81e4ae-39cb-4210-bea0-d6871a1c662e', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '4ce09b24-15f7-4841-ba11-00958f09447b', 'concept'::public.curated_course_node_type, 'Dodging and burning', null, 2),
  ('5bde8cf9-d3ea-4018-a496-99293ab190d9', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '4ce09b24-15f7-4841-ba11-00958f09447b', 'concept'::public.curated_course_node_type, 'Grain, clarity, and sharpening', null, 3),
  ('fcc202bd-6705-4c52-b6a4-1ef61f85b9d7', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'fd726c69-99ab-4a54-801b-b5c472ddd1bf', 'subtopic'::public.curated_course_node_type, 'Black and white traditions', 'The unit links tonal practice to major photographic histories and contemporary uses.', 2),
  ('8596fbdc-d251-4872-a769-03df33994b54', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'fcc202bd-6705-4c52-b6a4-1ef61f85b9d7', 'concept'::public.curated_course_node_type, 'Documentary black and white', null, 0),
  ('03c3329e-025e-4860-9ef2-8c2f8cb0072a', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'fcc202bd-6705-4c52-b6a4-1ef61f85b9d7', 'concept'::public.curated_course_node_type, 'Modernist form and abstraction', null, 1),
  ('13ef5952-1922-405a-afbe-42974010ca39', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'fcc202bd-6705-4c52-b6a4-1ef61f85b9d7', 'concept'::public.curated_course_node_type, 'Portraiture and atmosphere', null, 2),
  ('d868d680-0ad1-4d82-b041-4c5d81a01fe0', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'fcc202bd-6705-4c52-b6a4-1ef61f85b9d7', 'concept'::public.curated_course_node_type, 'Archival and fine-art print references', null, 3),
  ('0cff92c7-216e-41e1-b321-31bd0525a2e8', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', null, 'topic'::public.curated_course_node_type, 'Color Photography, White Balance, and Color Meaning', 'Color is technical, perceptual, emotional, and cultural. This unit teaches students to control color accuracy when needed and use color subjectively when meaning calls for it.', 6),
  ('ca40827b-2a0f-49b3-9914-8446e371dbae', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '0cff92c7-216e-41e1-b321-31bd0525a2e8', 'subtopic'::public.curated_course_node_type, 'White balance and color accuracy', 'Students learn how cameras interpret light color and how to correct or preserve color casts.', 0),
  ('f9e8c8ce-5e9c-4b95-86ac-a64d95a2efb3', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'ca40827b-2a0f-49b3-9914-8446e371dbae', 'concept'::public.curated_course_node_type, 'Kelvin temperature', null, 0),
  ('2a6c9630-5331-4540-9ee5-941a694dab9d', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'ca40827b-2a0f-49b3-9914-8446e371dbae', 'concept'::public.curated_course_node_type, 'Tint and mixed lighting', null, 1),
  ('362e6e14-ecac-4cc9-9300-b6f2071e49dd', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'ca40827b-2a0f-49b3-9914-8446e371dbae', 'concept'::public.curated_course_node_type, 'Gray cards and custom white balance', null, 2),
  ('438b9f78-896e-4aaa-8c52-2831ca2a6877', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'ca40827b-2a0f-49b3-9914-8446e371dbae', 'concept'::public.curated_course_node_type, 'RAW correction and color profiles', null, 3),
  ('f9c4a986-c010-4f35-9e76-4c1b0dcfb341', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '0cff92c7-216e-41e1-b321-31bd0525a2e8', 'subtopic'::public.curated_course_node_type, 'Color relationships and mood', 'Students develop a vocabulary for color as composition, symbolism, and atmosphere.', 1),
  ('630aba33-e08c-46e2-8601-e8b5921dca23', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'f9c4a986-c010-4f35-9e76-4c1b0dcfb341', 'concept'::public.curated_course_node_type, 'Hue, saturation, and luminosity', null, 0),
  ('56de0e33-b906-4df6-bdc2-0eab14738f5d', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'f9c4a986-c010-4f35-9e76-4c1b0dcfb341', 'concept'::public.curated_course_node_type, 'Complementary and analogous color', null, 1),
  ('4000d326-b722-437c-a4e1-bf93e0e0de04', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'f9c4a986-c010-4f35-9e76-4c1b0dcfb341', 'concept'::public.curated_course_node_type, 'Color contrast and harmony', null, 2),
  ('c7bf127e-d21d-4c4c-a6c5-0075fbedef9f', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'f9c4a986-c010-4f35-9e76-4c1b0dcfb341', 'concept'::public.curated_course_node_type, 'Cultural meanings of color', null, 3),
  ('edb14695-55ed-4bbe-86bf-55583626a2e1', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '0cff92c7-216e-41e1-b321-31bd0525a2e8', 'subtopic'::public.curated_course_node_type, 'Color in photographic history', 'The goal is to understand how color moved from commercial or amateur associations into art, documentary, and contemporary practice.', 2),
  ('3d679d4b-7a08-4e3b-b288-336332ef025d', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'edb14695-55ed-4bbe-86bf-55583626a2e1', 'concept'::public.curated_course_node_type, 'Early color processes', null, 0),
  ('a0920de8-704c-4609-b09e-2ed7d02ffb9d', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'edb14695-55ed-4bbe-86bf-55583626a2e1', 'concept'::public.curated_course_node_type, 'New color photography', null, 1),
  ('0722d931-9d90-42d2-bdc5-fe395fe99053', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'edb14695-55ed-4bbe-86bf-55583626a2e1', 'concept'::public.curated_course_node_type, 'Color documentary', null, 2),
  ('d0e8a2b6-bd80-4a65-b8be-36dc2e9e9ef2', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'edb14695-55ed-4bbe-86bf-55583626a2e1', 'concept'::public.curated_course_node_type, 'Digital color grading and screen culture', null, 3),
  ('085d6454-3b8b-456e-ae36-844a876c456a', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', null, 'topic'::public.curated_course_node_type, 'Lighting: Natural, Studio, Flash, and Continuous', 'Lighting is the craft of shaping visibility. Students learn to read existing light and build controlled light for portraits, still lifes, products, interiors, and conceptual work.', 7),
  ('5b4af646-9b31-4aee-be85-99116a46dae0', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '085d6454-3b8b-456e-ae36-844a876c456a', 'subtopic'::public.curated_course_node_type, 'Natural and available light', 'Students learn to work with daylight, ambient interiors, mixed sources, weather, time of day, and location constraints.', 0),
  ('6e0cb01e-86c2-45b0-8595-0425c6624e29', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '5b4af646-9b31-4aee-be85-99116a46dae0', 'concept'::public.curated_course_node_type, 'Golden hour, blue hour, and midday light', null, 0),
  ('40e1d1a6-4908-4139-a6a8-3470e5194b63', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '5b4af646-9b31-4aee-be85-99116a46dae0', 'concept'::public.curated_course_node_type, 'Window light and reflectors', null, 1),
  ('b88ffed2-4295-4ad8-b18b-78d717427fcd', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '5b4af646-9b31-4aee-be85-99116a46dae0', 'concept'::public.curated_course_node_type, 'Practical lights and mixed color', null, 2),
  ('c157a1a4-98af-41db-85df-839419b61803', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '5b4af646-9b31-4aee-be85-99116a46dae0', 'concept'::public.curated_course_node_type, 'Location scouting for light', null, 3),
  ('6e7b015a-52cd-4e83-b01c-5319e21bdde1', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '085d6454-3b8b-456e-ae36-844a876c456a', 'subtopic'::public.curated_course_node_type, 'Studio lighting fundamentals', 'Students practice controlled lighting setups that make form, texture, mood, and separation legible.', 1),
  ('35963ca3-6dd0-4a46-9574-dd66bdbbe0a9', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '6e7b015a-52cd-4e83-b01c-5319e21bdde1', 'concept'::public.curated_course_node_type, 'Key, fill, rim, and background lights', null, 0);
