  ('bafb0b85-4deb-4953-b3cc-917d1956fe37', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '8cf94584-f4f8-4d3d-bebc-0e7d29bfc4b8', 'concept'::public.curated_course_node_type, 'Modifiers and grip safety', null, 2),
  ('6971cec8-fe9e-4330-9fa8-8bc10b80ce04', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '8cf94584-f4f8-4d3d-bebc-0e7d29bfc4b8', 'concept'::public.curated_course_node_type, 'Lighting diagrams and repeatability', null, 3),
  ('407f14b3-038a-41dc-ab11-8c42297c2aa1', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', null, 'topic'::public.curated_course_node_type, 'Portraiture, Studio Practice, and Subject Collaboration', 'Portraiture is a relationship as much as a picture. This unit focuses on trust, direction, lighting, gesture, environment, identity, consent, and collaboration with photographed people.', 8),
  ('f2ed92ba-8061-4524-ac01-88609e0853e9', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '407f14b3-038a-41dc-ab11-8c42297c2aa1', 'subtopic'::public.curated_course_node_type, 'Portrait strategies', 'Students compare formal, environmental, candid, staged, self-portrait, and collaborative portrait approaches.', 0),
  ('0925cf17-a040-4a09-b61a-9512d9650bd3', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'f2ed92ba-8061-4524-ac01-88609e0853e9', 'concept'::public.curated_course_node_type, 'Expression, pose, and gesture', null, 0),
  ('0dd5be00-8dae-43b6-8aa3-89dd196ad4fa', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'f2ed92ba-8061-4524-ac01-88609e0853e9', 'concept'::public.curated_course_node_type, 'Background and environment', null, 1),
  ('9ec073bd-a0a5-410a-8c0e-01694dad52d3', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'f2ed92ba-8061-4524-ac01-88609e0853e9', 'concept'::public.curated_course_node_type, 'Gaze, address, and power', null, 2),
  ('fa82b6ce-15bf-498a-9c2f-d03d4fbb4df7', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'f2ed92ba-8061-4524-ac01-88609e0853e9', 'concept'::public.curated_course_node_type, 'Self-portraiture and identity', null, 3),
  ('a37dcd2a-9ba6-4525-81ea-401729998777', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '407f14b3-038a-41dc-ab11-8c42297c2aa1', 'subtopic'::public.curated_course_node_type, 'Working with subjects', 'Students learn how communication, consent, scheduling, comfort, and direction affect both ethics and image quality.', 1),
  ('97329e00-608f-4dd6-ade1-2a591636c255', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'a37dcd2a-9ba6-4525-81ea-401729998777', 'concept'::public.curated_course_node_type, 'Pre-shoot conversation', null, 0),
  ('a7fffb7b-bc32-43f1-bbe2-ab337dc579fa', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'a37dcd2a-9ba6-4525-81ea-401729998777', 'concept'::public.curated_course_node_type, 'Model releases and expectations', null, 1),
  ('12ef1e2d-b52b-4224-96fd-2db2655cf794', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'a37dcd2a-9ba6-4525-81ea-401729998777', 'concept'::public.curated_course_node_type, 'Directing without coercion', null, 2),
  ('3b42f971-3a06-4c62-a97c-669fa2d75e79', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'a37dcd2a-9ba6-4525-81ea-401729998777', 'concept'::public.curated_course_node_type, 'Care, dignity, and representation', null, 3),
  ('2fb29abc-2748-45d8-8d2d-bc7062d2b036', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '407f14b3-038a-41dc-ab11-8c42297c2aa1', 'subtopic'::public.curated_course_node_type, 'Studio portrait workflow', 'The goal is to combine technical control with human presence.', 2),
  ('bcf15dd3-735c-462e-930e-25260bda601e', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '2fb29abc-2748-45d8-8d2d-bc7062d2b036', 'concept'::public.curated_course_node_type, 'Lighting setups for faces and bodies', null, 0),
  ('90196dd0-8ecb-49d0-9a4a-5ecad615663e', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '2fb29abc-2748-45d8-8d2d-bc7062d2b036', 'concept'::public.curated_course_node_type, 'Lens choice and distance', null, 1),
  ('6ed49767-dd77-466a-bfd3-5687f0c0d015', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '2fb29abc-2748-45d8-8d2d-bc7062d2b036', 'concept'::public.curated_course_node_type, 'Tethering and review with subjects', null, 2),
  ('d80df667-19ac-4ea6-8a4e-859ee9addc7f', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '2fb29abc-2748-45d8-8d2d-bc7062d2b036', 'concept'::public.curated_course_node_type, 'Retouching boundaries', null, 3),
  ('b53ec0f6-a22e-4f10-b14b-df4c8d63fb5c', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', null, 'topic'::public.curated_course_node_type, 'Documentary, Street, Photojournalism, and Visual Storytelling', 'Documentary photography asks students to make images about real people, places, events, and issues with care. This unit builds story structure, field practice, captions, editing, and ethical responsibility.', 9),
  ('46ad71ee-afb8-45db-b45c-25b25fe06acc', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'b53ec0f6-a22e-4f10-b14b-df4c8d63fb5c', 'subtopic'::public.curated_course_node_type, 'Documentary approaches', 'Students learn that documentary ranges from observation to advocacy, essay, collaboration, and long-form research.', 0),
  ('65c1fed7-f2f9-4068-8f50-c0653042a75a', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '46ad71ee-afb8-45db-b45c-25b25fe06acc', 'concept'::public.curated_course_node_type, 'Observation and access', null, 0),
  ('3c2b74e0-ee77-40d0-b7ae-b86c9ade0637', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '46ad71ee-afb8-45db-b45c-25b25fe06acc', 'concept'::public.curated_course_node_type, 'Photo essays and narrative arcs', null, 1),
  ('83f58337-d211-4ee3-8847-155d9701cbc6', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '46ad71ee-afb8-45db-b45c-25b25fe06acc', 'concept'::public.curated_course_node_type, 'Caption and context', null, 2),
  ('d327989c-d2b9-4bcc-b139-1a7bafbe4e7b', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '46ad71ee-afb8-45db-b45c-25b25fe06acc', 'concept'::public.curated_course_node_type, 'Long-term projects and immersion', null, 3),
  ('b1b93385-45ad-4a30-ae90-2efb68be0fa0', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'b53ec0f6-a22e-4f10-b14b-df4c8d63fb5c', 'subtopic'::public.curated_course_node_type, 'Street and public-space photography', 'Students examine spontaneity, publicness, law, safety, consent, and the social behavior of photographing in public.', 1),
  ('c6cca3b5-5d85-4a5f-9655-24ad6f317c5f', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'b1b93385-45ad-4a30-ae90-2efb68be0fa0', 'concept'::public.curated_course_node_type, 'Anticipation and layering', null, 0),
  ('a3f99312-cca7-4511-b827-8261b4a04ce9', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'b1b93385-45ad-4a30-ae90-2efb68be0fa0', 'concept'::public.curated_course_node_type, 'Gesture and coincidence', null, 1),
  ('d5c08565-bd45-48d8-87bb-d110a54ddaee', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'b1b93385-45ad-4a30-ae90-2efb68be0fa0', 'concept'::public.curated_course_node_type, 'Public/private boundaries', null, 2),
  ('8d254c25-03af-4faf-a633-e4ae24d81e05', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'b1b93385-45ad-4a30-ae90-2efb68be0fa0', 'concept'::public.curated_course_node_type, 'Respectful field conduct', null, 3),
  ('636d801c-76f3-48ba-a426-951cde6f450c', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'b53ec0f6-a22e-4f10-b14b-df4c8d63fb5c', 'subtopic'::public.curated_course_node_type, 'Photojournalism standards', 'The unit introduces verification, caption accuracy, manipulation limits, deadlines, and public trust.', 2),
  ('2fd5b4c1-fdd8-4600-925c-8b44ba76238f', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '636d801c-76f3-48ba-a426-951cde6f450c', 'concept'::public.curated_course_node_type, 'News values and visual evidence', null, 0),
  ('f600489e-d2fe-458e-9bae-5ee1f958837d', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '636d801c-76f3-48ba-a426-951cde6f450c', 'concept'::public.curated_course_node_type, 'Caption writing and metadata', null, 1),
  ('df42caec-e0c9-4003-9a7e-f517a2a9b92f', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '636d801c-76f3-48ba-a426-951cde6f450c', 'concept'::public.curated_course_node_type, 'Editorial ethics and staging limits', null, 2),
  ('9985f223-d2fa-42ad-a069-75d8aa1f4975', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '636d801c-76f3-48ba-a426-951cde6f450c', 'concept'::public.curated_course_node_type, 'Trauma-aware reporting and minimizing harm', null, 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('52a460ad-24b3-4ca1-8340-105232e93851', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', null, 'topic'::public.curated_course_node_type, 'Constructed, Conceptual, Staged, and Experimental Photography', 'Photography is not limited to capture. Students explore images built through staging, performance, intervention, appropriation, abstraction, process, and conceptual systems.', 10),
  ('ea10da0b-a84b-466d-bfc3-68da582765a1', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '52a460ad-24b3-4ca1-8340-105232e93851', 'subtopic'::public.curated_course_node_type, 'Staged and constructed images', 'Students learn how props, sets, performance, lighting, costume, and narrative ambiguity can create photographic worlds.', 0),
  ('91605668-f0bc-456a-9be6-ca2a41803c2e', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'ea10da0b-a84b-466d-bfc3-68da582765a1', 'concept'::public.curated_course_node_type, 'Tableau and mise-en-scene', null, 0),
  ('4fc764c1-8e0e-4be4-bad0-56a1212b5cc4', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'ea10da0b-a84b-466d-bfc3-68da582765a1', 'concept'::public.curated_course_node_type, 'Performance for the camera', null, 1),
  ('6720d1a8-1223-4336-b23d-ee9a52ba32c3', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'ea10da0b-a84b-466d-bfc3-68da582765a1', 'concept'::public.curated_course_node_type, 'Still life and constructed scenes', null, 2),
  ('3183d9ce-f255-474b-af26-6ab08a904aef', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'ea10da0b-a84b-466d-bfc3-68da582765a1', 'concept'::public.curated_course_node_type, 'Fiction, fantasy, and ambiguity', null, 3),
  ('a7676089-d793-489f-a211-cea5bbf17c61', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '52a460ad-24b3-4ca1-8340-105232e93851', 'subtopic'::public.curated_course_node_type, 'Conceptual and process-based work', 'Students explore photographic projects driven by rules, systems, typologies, archives, or repeated actions.', 1),
  ('2e000854-0e9f-4290-b109-dfcd199b0229', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'a7676089-d793-489f-a211-cea5bbf17c61', 'concept'::public.curated_course_node_type, 'Typology and seriality', null, 0),
  ('a7870c5e-9ec0-4f7f-b56f-17e9a0e0fc10', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'a7676089-d793-489f-a211-cea5bbf17c61', 'concept'::public.curated_course_node_type, 'Instruction-based work', null, 1),
  ('cf0480b8-c225-4c26-8682-a93b7db83df5', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'a7676089-d793-489f-a211-cea5bbf17c61', 'concept'::public.curated_course_node_type, 'Chance and constraint', null, 2),
  ('b79fce18-2b38-471e-a085-58728e09caaa', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'a7676089-d793-489f-a211-cea5bbf17c61', 'concept'::public.curated_course_node_type, 'Photography as idea and evidence', null, 3),
  ('0d014ec7-3b0d-4673-8a3e-835061d05fea', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '52a460ad-24b3-4ca1-8340-105232e93851', 'subtopic'::public.curated_course_node_type, 'Experimental image-making', 'The unit invites risk with camera-less, hybrid, digital, and material methods.', 2),
  ('2d7fe260-e97d-450f-bec7-e1423de52166', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '0d014ec7-3b0d-4673-8a3e-835061d05fea', 'concept'::public.curated_course_node_type, 'Scanography and photocollage', null, 0),
  ('23e5ad7d-bdc5-48f4-be0d-cb4e81fd9e86', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '0d014ec7-3b0d-4673-8a3e-835061d05fea', 'concept'::public.curated_course_node_type, 'Glitch, abstraction, and distortion', null, 1),
  ('3ad37227-ddc0-4868-86a0-0ca662e0fb6f', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '0d014ec7-3b0d-4673-8a3e-835061d05fea', 'concept'::public.curated_course_node_type, 'Projection and rephotography', null, 2),
  ('8f1e7edf-531f-4e3c-9b34-284eff55e21f', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '0d014ec7-3b0d-4673-8a3e-835061d05fea', 'concept'::public.curated_course_node_type, 'Mixed media and installation', null, 3),
  ('a4533db6-ee81-4080-b8a8-aa15aba256d3', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', null, 'topic'::public.curated_course_node_type, 'Analog Processes, Darkroom, Alternative Processes, and Materiality', 'Analog and alternative processes teach students that photographs are objects, chemicals, surfaces, and time-based traces. Even digital photographers gain deeper craft from understanding material process.', 11),
  ('d21131ed-fa42-4d33-a58e-a58af0704443', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'a4533db6-ee81-4080-b8a8-aa15aba256d3', 'subtopic'::public.curated_course_node_type, 'Film and darkroom overview', 'Students learn the conceptual and practical foundations of film exposure, development, contact sheets, enlarging, and print evaluation.', 0),
  ('f9409688-a878-4d81-93eb-d6a929c8632a', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'd21131ed-fa42-4d33-a58e-a58af0704443', 'concept'::public.curated_course_node_type, 'Film stocks and formats', null, 0),
  ('9aa42c83-324c-4ca4-a357-b8586b20dbbf', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'd21131ed-fa42-4d33-a58e-a58af0704443', 'concept'::public.curated_course_node_type, 'Developing, contact sheets, and negatives', null, 1),
  ('43dc900a-0143-433e-bc4b-b50e3e0d1e44', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'd21131ed-fa42-4d33-a58e-a58af0704443', 'concept'::public.curated_course_node_type, 'Enlarger basics', null, 2),
  ('569bb842-05d0-400d-af55-9d0cd698a22d', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'd21131ed-fa42-4d33-a58e-a58af0704443', 'concept'::public.curated_course_node_type, 'Dodging, burning, and test strips', null, 3),
  ('b849741a-84f3-41e3-ac1d-a4e323fe5671', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'a4533db6-ee81-4080-b8a8-aa15aba256d3', 'subtopic'::public.curated_course_node_type, 'Alternative and historical processes', 'Students explore hand-made photographic surfaces and the history of image technologies.', 1),
  ('37f89702-d5ae-4937-a43b-177d92f2f032', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'b849741a-84f3-41e3-ac1d-a4e323fe5671', 'concept'::public.curated_course_node_type, 'Cyanotype and photograms', null, 0),
  ('7bf9eed6-5da0-49ae-99ae-724559b4fe9f', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'b849741a-84f3-41e3-ac1d-a4e323fe5671', 'concept'::public.curated_course_node_type, 'Pinhole photography', null, 1),
  ('9e62aa2c-7583-43cb-8450-fddb481e5ccd', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'b849741a-84f3-41e3-ac1d-a4e323fe5671', 'concept'::public.curated_course_node_type, 'Salt, albumen, platinum, and gum overview', null, 2),
  ('235f5986-4b89-4fec-88a6-617cf0f36258', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'b849741a-84f3-41e3-ac1d-a4e323fe5671', 'concept'::public.curated_course_node_type, 'Process variables and experimentation', null, 3),
  ('bcfba9a4-b303-485c-baff-4efb22a325d1', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'a4533db6-ee81-4080-b8a8-aa15aba256d3', 'subtopic'::public.curated_course_node_type, 'Photograph as object', 'The goal is to think beyond screen images toward paper, scale, surface, edition, installation, and conservation.', 2),
  ('fc31091d-b109-414a-ad9b-1adf699b21d7', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'bcfba9a4-b303-485c-baff-4efb22a325d1', 'concept'::public.curated_course_node_type, 'Paper types and surface', null, 0),
  ('62c1d104-1030-44ec-bfb1-790e0221a435', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'bcfba9a4-b303-485c-baff-4efb22a325d1', 'concept'::public.curated_course_node_type, 'Editioning and handling', null, 1),
  ('dd77a0a9-bdd1-436c-aa0f-d50715c7ba33', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'bcfba9a4-b303-485c-baff-4efb22a325d1', 'concept'::public.curated_course_node_type, 'Mounting and framing', null, 2),
  ('fe417e8b-c6c7-46cf-a230-7890d5929389', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'bcfba9a4-b303-485c-baff-4efb22a325d1', 'concept'::public.curated_course_node_type, 'Object care and storage', null, 3),
  ('2ae127a7-1fa1-4bef-aed6-2a3d15a96766', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', null, 'topic'::public.curated_course_node_type, 'Sequencing, Series, Photobooks, Text, and Exhibition Design', 'Photographs often become powerful through relation: sequence, rhythm, repetition, edit, scale, caption, and installation. This unit teaches students to make bodies of work rather than isolated good images.', 12),
  ('ca5bfdae-a591-42a9-bd6f-51e94461e763', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', '2ae127a7-1fa1-4bef-aed6-2a3d15a96766', 'subtopic'::public.curated_course_node_type, 'Series development', 'Students learn how projects cohere through subject, method, visual language, concept, and edit.', 0),
  ('5cfd71eb-6e30-481e-916e-0963e0db3b47', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', 'ca5bfdae-a591-42a9-bd6f-51e94461e763', 'concept'::public.curated_course_node_type, 'Project statements and constraints', null, 0),
