  ('619f3a96-8111-4303-95d6-9366ee03e79e', 'd0e1f2a3-4b5c-4d62-9a12-2b3c4d5e6f82', null, 'topic'::public.curated_course_node_type, 'Ethics, Consent, Representation, Copyright, and Image Circulation', 'Photography has real effects on people and communities. This unit helps students make ethically informed decisions about consent, representation, manipulation, authorship, copyright, privacy, and circulation.', 13),
